INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (4, 'g7', 1, 2, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '数轴上点 A 表示 −5，将 A 向右移动 8 个单位得到点 B，则 B 表示的数是', '["−8","3","5","8"]', '{"index":1}', '动态随机题型（每次闯关随机生成参数与选项）', 'c1_g1_0', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>{const k=R(2,6);return mkg(\'数轴上点 A 表示 −\'+k+\'，将 A 向右移动 \'+(k+3)+\' 个单位得到点 B，则 B 表示的数是\',\'3\',[\'−\'+(k+3),String(k),String(k+3)])}","sampleStem":"数轴上点 A 表示 −5，将 A 向右移动 8 个单位得到点 B，则 B 表示的数是"}', 2, '["初一","第1章 有理数","动态随机"]', 'PROTOTYPE', 1, 1, 1);
INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (5, 'g7', 1, 2, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '若 |x| = 4，则 x =', '["0","-4","4","±4"]', '{"index":3}', '动态随机题型（每次闯关随机生成参数与选项）', 'c1_g1_1', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>{const k=R(2,9);return mkg(\'若 |x| = \'+k+\'，则 x =\',\'±\'+k,[String(k),String(-k),\'0\'])}","sampleStem":"若 |x| = 4，则 x ="}', 2, '["初一","第1章 有理数","动态随机"]', 'PROTOTYPE', 1, 2, 1);
INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (6, 'g7', 1, 2, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '计算 (−1)^2026 + (−1)^2028 =', '["−1","1","0","2"]', '{"index":3}', '动态随机题型（每次闯关随机生成参数与选项）', 'c1_g1_2', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>{const n=R(2023,2027);const ans=(n%2===0)?\'2\':\'−2\';return mkg(\'计算 (−1)^\'+n+\' + (−1)^\'+(n+2)+\' =\',ans,[\'0\',\'1\',\'−1\']);}","sampleStem":"计算 (−1)^2026 + (−1)^2028 ="}', 2, '["初一","第1章 有理数","动态随机"]', 'PROTOTYPE', 1, 3, 1);
INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (7, 'g7', 1, 3, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '若 |x−5| + |y+3| = 0，则 x+y =', '["-8","-2","2","8"]', '{"index":2}', '动态随机题型（每次闯关随机生成参数与选项）', 'c1_g2_0', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>{const a=R(1,5),b=R(1,5);return mkg(\'若 |x−\'+a+\'| + |y+\'+b+\'| = 0，则 x+y =\',String(a-b),[String(a+b),String(-a+b),String(-a-b)])}","sampleStem":"若 |x−5| + |y+3| = 0，则 x+y ="}', 3, '["初一","第1章 有理数","动态随机"]', 'PROTOTYPE', 1, 1, 1);
INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (8, 'g7', 1, 3, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '有理数 a、b 在数轴上：b<0<a 且 |b|>|a|，则 a+b 的符号是', '["负","正","无法确定","0"]', '{"index":0}', '动态随机题型（每次闯关随机生成参数与选项）', 'c1_g2_1', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>mkg(\'有理数 a、b 在数轴上：b<0<a 且 |b|>|a|，则 a+b 的符号是\',\'负\',[\'正\',\'0\',\'无法确定\'])","sampleStem":"有理数 a、b 在数轴上：b<0<a 且 |b|>|a|，则 a+b 的符号是"}', 3, '["初一","第1章 有理数","动态随机"]', 'PROTOTYPE', 1, 2, 1);
INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (9, 'g7', 1, 3, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '已知 x<−4，化简 |x+4| − |1−x| =', '["−5","−2","4","2x+5"]', '{"index":0}', '动态随机题型（每次闯关随机生成参数与选项）', 'c1_g2_2', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>{const k=R(4,9);return mkg(\'已知 x<−\'+k+\'，化简 |x+\'+k+\'| − |1−x| =\',\'−\'+(k+1),[\'4\',\'2x+\'+(k+1),\'−2\']);}","sampleStem":"已知 x<−4，化简 |x+4| − |1−x| ="}', 3, '["初一","第1章 有理数","动态随机"]', 'PROTOTYPE', 1, 3, 1);
