INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (27, 'g7', 3, 9, 'STATIC', 'SINGLE_CHOICE', '等式的性质：两边同时加上同一个数，等式', '["仍成立","不成立","变号","无法确定"]', '{"index":0}', '', NULL, NULL, 1, '["初一","第3章 一元一次方程"]', 'PROTOTYPE', 1, 3, 1);
INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (28, 'g7', 3, 10, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '解方程 4(x−1)=8，得 x =', '["2","3","4","12"]', '{"index":1}', '动态随机题型（每次闯关随机生成参数与选项）', 'c3_g1_0', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>{const a=R(2,4),x=R(2,6);return mkg(\'解方程 \'+a+\'(x−1)=\'+(a*x-a)+\'，得 x =\',String(x),[String(x+1),String(x-1),String(a*x)])}","sampleStem":"解方程 4(x−1)=8，得 x ="}', 2, '["初一","第3章 一元一次方程","动态随机"]', 'PROTOTYPE', 1, 1, 1);
INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (29, 'g7', 3, 10, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '方程 x/3 = -1 的解是', '["2","-1","4","-3"]', '{"index":3}', '动态随机题型（每次闯关随机生成参数与选项）', 'c3_g1_1', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>{const a=R(2,5),m=R(-3,3);if(m===0){return mkg(\'方程 x/\'+a+\' = 1 的解是\',String(a),[String(-a),String(a+1),\'1\']);}return mkg(\'方程 x/\'+a+\' = \'+m+\' 的解是\',String(a*m),[String(a+m),String(a-m),String(m)])}","sampleStem":"方程 x/3 = -1 的解是"}', 2, '["初一","第3章 一元一次方程","动态随机"]', 'PROTOTYPE', 1, 2, 1);
INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (30, 'g7', 3, 10, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '甲数比乙数大 5，甲乙两数之和为 23，则乙数是', '["14","4","9","18"]', '{"index":2}', '动态随机题型（每次闯关随机生成参数与选项）', 'c3_g1_2', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>{const y=R(2,9),d=R(1,6);return mkg(\'甲数比乙数大 \'+d+\'，甲乙两数之和为 \'+(2*y+d)+\'，则乙数是\',String(y),[String(y+d),String(2*y),String(y-d)]);}","sampleStem":"甲数比乙数大 5，甲乙两数之和为 23，则乙数是"}', 2, '["初一","第3章 一元一次方程","动态随机"]', 'PROTOTYPE', 1, 3, 1);
INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (31, 'g7', 3, 11, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '某商品按利润率 50% 定价，售价 300 元，则进价为', '["200 元","300 元","190 元","220 元"]', '{"index":0}', '动态随机题型（每次闯关随机生成参数与选项）', 'c3_g2_0', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>{const s=100*[3,6][R(0,1)];const r=[25,50][R(0,1)];const x=s*100/(100+r);return mkg(\'某商品按利润率 \'+r+\'% 定价，售价 \'+s+\' 元，则进价为\',String(x)+\' 元\',[String(x+20)+\' 元\',String(x-10)+\' 元\',String(s)+\' 元\'])}","sampleStem":"某商品按利润率 50% 定价，售价 300 元，则进价为"}', 3, '["初一","第3章 一元一次方程","动态随机"]', 'PROTOTYPE', 1, 1, 1);
INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (32, 'g7', 3, 11, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '若关于 x 的方程 2x+2 = 12 有解 x=5，则方程 2x+2 = 10 的解是', '["5","4","6","-5"]', '{"index":1}', '动态随机题型（每次闯关随机生成参数与选项）', 'c3_g2_1', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>{const a=R(2,5),x=R(2,6);return mkg(\'若关于 x 的方程 \'+a+\'x+\'+a+\' = \'+(a*x+a)+\' 有解 x=\'+x+\'，则方程 \'+a+\'x+\'+a+\' = \'+(a*x)+\' 的解是\',String(x-1),[String(x),String(x+1),String(-x)])}","sampleStem":"若关于 x 的方程 2x+2 = 12 有解 x=5，则方程 2x+2 = 10 的解是"}', 3, '["初一","第3章 一元一次方程","动态随机"]', 'PROTOTYPE', 1, 2, 1);
INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (33, 'g7', 3, 11, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '甲乙两地相距 120 km，汽车速度 60 km/h，行驶 t 小时后距乙地 30 km（已过乙地继续前行），则已行驶时间为', '["1.5 小时","3 小时","2.5 小时","2 小时"]', '{"index":0}', '动态随机题型（每次闯关随机生成参数与选项）', 'c3_g2_2', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>{const v=60,t=R(2,4);return mkg(\'甲乙两地相距 \'+(v*t)+\' km，汽车速度 \'+v+\' km/h，行驶 t 小时后距乙地 30 km（已过乙地继续前行），则已行驶时间为\',(v*t-30)/v+\' 小时\',[t+\' 小时\',(t+1)+\' 小时\',(v*t+30)/v+\' 小时\']);}","sampleStem":"甲乙两地相距 120 km，汽车速度 60 km/h，行驶 t 小时后距乙地 30 km（已过乙地继续前行），则已行驶时间为"}', 3, '["初一","第3章 一元一次方程","动态随机"]', 'PROTOTYPE', 1, 3, 1);
INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (34, 'g7', 3, 12, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '一艘船顺流航行速度为 26 km/h，逆流为 18 km/h，则水流速度为', '["4 km/h","8 km/h","2 km/h","22 km/h"]', '{"index":0}', '动态随机题型（每次闯关随机生成参数与选项）', 'c3_g3_0', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>mkg(\'一艘船顺流航行速度为 26 km/h，逆流为 18 km/h，则水流速度为\',\'4 km/h\',[\'2 km/h\',\'22 km/h\',\'8 km/h\'])","sampleStem":"一艘船顺流航行速度为 26 km/h，逆流为 18 km/h，则水流速度为"}', 4, '["初一","第3章 一元一次方程","动态随机"]', 'PROTOTYPE', 1, 1, 1);
INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (35, 'g7', 3, 12, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '分书方案：若每人分 3 本则多 8 本，每人分 6 本则缺 4 本，则总人数为', '["4","5","6","3"]', '{"index":0}', '动态随机题型（每次闯关随机生成参数与选项）', 'c3_g3_1', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>{const p=[[4,12],[5,6],[6,4],[7,3]][R(0,3)];return mkg(\'分书方案：若每人分 3 本则多 8 本，每人分 \'+p[0]+\' 本则缺 4 本，则总人数为\',String(p[1]),[String(p[1]+1),String(p[1]-1),String(p[1]+2)])}","sampleStem":"分书方案：若每人分 3 本则多 8 本，每人分 6 本则缺 4 本，则总人数为"}', 4, '["初一","第3章 一元一次方程","动态随机"]', 'PROTOTYPE', 1, 2, 1);
INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (36, 'g7', 3, 12, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '关于 x 的方程 (m−1)x = m−1 的解为任意有理数，则 m =', '["0","−1","1","2"]', '{"index":2}', '动态随机题型（每次闯关随机生成参数与选项）', 'c3_g3_2', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>{return mkg(\'关于 x 的方程 (m−1)x = m−1 的解为任意有理数，则 m =\',\'1\',[\'0\',\'−1\',\'2\']);}","sampleStem":"关于 x 的方程 (m−1)x = m−1 的解为任意有理数，则 m ="}', 4, '["初一","第3章 一元一次方程","动态随机"]', 'PROTOTYPE', 1, 3, 1);
