INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (49, 'g7', 5, 17, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '两直线相交，一个角为 64°，则它的对顶角为', '["32°","64°","26°","116°"]', '{"index":1}', '动态随机题型（每次闯关随机生成参数与选项）', 'c5_g0_0', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>{const a=R(35,85);return mkg(\'两直线相交，一个角为 \'+a+\'°，则它的对顶角为\',a+\'°\',[(180-a)+\'°\',(90-a)+\'°\',(a/2)+\'°\'])}","sampleStem":"两直线相交，一个角为 64°，则它的对顶角为"}', 1, '["初一","第5章 相交线与平行线","动态随机"]', 'PROTOTYPE', 1, 1, 1);
INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (50, 'g7', 5, 17, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '两直线相交，一个角为 73°，则它的邻补角为', '["107°","17°","73°","163°"]', '{"index":0}', '动态随机题型（每次闯关随机生成参数与选项）', 'c5_g0_1', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>{const a=R(35,85);return mkg(\'两直线相交，一个角为 \'+a+\'°，则它的邻补角为\',(180-a)+\'°\',[a+\'°\',(90-a)+\'°\',(90+a)+\'°\'])}","sampleStem":"两直线相交，一个角为 73°，则它的邻补角为"}', 1, '["初一","第5章 相交线与平行线","动态随机"]', 'PROTOTYPE', 1, 2, 1);
INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (51, 'g7', 5, 17, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '两直线平行，同位角相等。若同位角之一为 44°，则另一个为', '["134°","136°","44°","74°"]', '{"index":2}', '动态随机题型（每次闯关随机生成参数与选项）', 'c5_g0_2', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>{const a=R(35,85);return mkg(\'两直线平行，同位角相等。若同位角之一为 \'+a+\'°，则另一个为\',a+\'°\',[(180-a)+\'°\',(90+a)+\'°\',(a+30)+\'°\']);}","sampleStem":"两直线平行，同位角相等。若同位角之一为 44°，则另一个为"}', 1, '["初一","第5章 相交线与平行线","动态随机"]', 'PROTOTYPE', 1, 3, 1);
INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (52, 'g7', 5, 18, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '两直线平行，内错角相等。若内错角之一为 76°，则另一个为', '["14°","96°","76°","104°"]', '{"index":2}', '动态随机题型（每次闯关随机生成参数与选项）', 'c5_g1_0', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>{const a=R(35,85);return mkg(\'两直线平行，内错角相等。若内错角之一为 \'+a+\'°，则另一个为\',a+\'°\',[(180-a)+\'°\',(a+20)+\'°\',(90-a)+\'°\'])}","sampleStem":"两直线平行，内错角相等。若内错角之一为 76°，则另一个为"}', 2, '["初一","第5章 相交线与平行线","动态随机"]', 'PROTOTYPE', 1, 1, 1);
INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (53, 'g7', 5, 18, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '两直线平行，同旁内角互补。若一个为 74°，则另一个为', '["164°","254°","74°","106°"]', '{"index":3}', '动态随机题型（每次闯关随机生成参数与选项）', 'c5_g1_1', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>{const a=R(35,85);return mkg(\'两直线平行，同旁内角互补。若一个为 \'+a+\'°，则另一个为\',(180-a)+\'°\',[a+\'°\',(90+a)+\'°\',(180+a)+\'°\'])}","sampleStem":"两直线平行，同旁内角互补。若一个为 74°，则另一个为"}', 2, '["初一","第5章 相交线与平行线","动态随机"]', 'PROTOTYPE', 1, 2, 1);
INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (54, 'g7', 5, 18, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '直线外一点到这条直线的距离，指的是该点到直线的', '["斜线段的长度","最短斜线段的长度","任意连线的长度","垂线段的长度"]', '{"index":3}', '动态随机题型（每次闯关随机生成参数与选项）', 'c5_g1_2', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>{return mkg(\'直线外一点到这条直线的距离，指的是该点到直线的\',\'垂线段的长度\',[\'斜线段的长度\',\'任意连线的长度\',\'最短斜线段的长度\']);}","sampleStem":"直线外一点到这条直线的距离，指的是该点到直线的"}', 2, '["初一","第5章 相交线与平行线","动态随机"]', 'PROTOTYPE', 1, 3, 1);
INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (55, 'g7', 5, 19, 'STATIC', 'SINGLE_CHOICE', '两平行线被第三条直线所截，一对同旁内角的角平分线互相', '["垂直","平行","相交成 60° 角","重合"]', '{"index":0}', '', NULL, NULL, 3, '["初一","第5章 相交线与平行线"]', 'PROTOTYPE', 1, 1, 1);
