INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (57, 'g7', 5, 19, 'STATIC', 'SINGLE_CHOICE', '点到直线的距离是', '["垂线段的长度","垂线","最短的斜线段","点到线上任意点的距离"]', '{"index":0}', '', NULL, NULL, 3, '["初一","第5章 相交线与平行线"]', 'PROTOTYPE', 1, 3, 1);
INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (58, 'g7', 5, 20, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '∠1 与 ∠2 是两平行线被截得的同旁内角，∠1 = 3∠2 − 100°，则 ∠1 =', '["55°","70°","110°","110°+1"]', '{"index":2}', '动态随机题型（每次闯关随机生成参数与选项）', 'c5_g3_0', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>{const b=[20,60,100,140][R(0,3)];const y=(180+b)/4;const x=3*y-b;return mkg(\'∠1 与 ∠2 是两平行线被截得的同旁内角，∠1 = 3∠2 − \'+b+\'°，则 ∠1 =\',x+\'°\',[y+\'°\',(180-x)+\'°\',(x/2)+\'°\'])}","sampleStem":"∠1 与 ∠2 是两平行线被截得的同旁内角，∠1 = 3∠2 − 100°，则 ∠1 ="}', 4, '["初一","第5章 相交线与平行线","动态随机"]', 'PROTOTYPE', 1, 1, 1);
INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (59, 'g7', 5, 20, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', 'AB∥CD，点 P 在两平行线之间，∠APB 的两边分别与两平行线相交，同侧的 ∠1=47°、∠2=40°，则 ∠APB =', '["43.5°","7°","93°","87°"]', '{"index":3}', '动态随机题型（每次闯关随机生成参数与选项）', 'c5_g3_1', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>{const a=R(30,50),b=R(30,50);return mkg(\'AB∥CD，点 P 在两平行线之间，∠APB 的两边分别与两平行线相交，同侧的 ∠1=\'+a+\'°、∠2=\'+b+\'°，则 ∠APB =\',(a+b)+\'°\',[Math.abs(a-b)+\'°\',(180-a-b)+\'°\',(a+b)/2+\'°\'])}","sampleStem":"AB∥CD，点 P 在两平行线之间，∠APB 的两边分别与两平行线相交，同侧的 ∠1=47°、∠2=40°，则 ∠APB ="}', 4, '["初一","第5章 相交线与平行线","动态随机"]', 'PROTOTYPE', 1, 2, 1);
INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (60, 'g7', 5, 20, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', 'AB∥CD，∠ABE=69°，BE⊥CE 于 E，点 E 在 AB 与 CD 之间，则 ∠DCE =', '["69°","21°","111°","159°"]', '{"index":1}', '动态随机题型（每次闯关随机生成参数与选项）', 'c5_g3_2', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>{const a=R(40,70);return mkg(\'AB∥CD，∠ABE=\'+a+\'°，BE⊥CE 于 E，点 E 在 AB 与 CD 之间，则 ∠DCE =\',(90-a)+\'°\',[a+\'°\',(180-a)+\'°\',(90+a)+\'°\']);}","sampleStem":"AB∥CD，∠ABE=69°，BE⊥CE 于 E，点 E 在 AB 与 CD 之间，则 ∠DCE ="}', 4, '["初一","第5章 相交线与平行线","动态随机"]', 'PROTOTYPE', 1, 3, 1);
INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (61, 'g7', 6, 21, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '√81 =', '["10","9","−9","41.5"]', '{"index":1}', '动态随机题型（每次闯关随机生成参数与选项）', 'c6_g0_0', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>{const n=[4,9,16,25,36,49,64,81,100][R(0,8)];return mkg(\'√\'+n+\' =\',String(Math.sqrt(n)),[String(Math.sqrt(n)+1),\'−\'+Math.sqrt(n),String(n/2+1)])}","sampleStem":"√81 ="}', 1, '["初一","第6章 实数","动态随机"]', 'PROTOTYPE', 1, 1, 1);
INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (62, 'g7', 6, 21, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '∛8 =', '["±2","2.6666666666666665","2","3"]', '{"index":2}', '动态随机题型（每次闯关随机生成参数与选项）', 'c6_g0_1', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>{const n=[8,27,64,125,216][R(0,4)];return mkg(\'∛\'+n+\' =\',String(Math.cbrt(n)),[String(Math.cbrt(n)+1),\'±\'+Math.cbrt(n),String(n/3)])}","sampleStem":"∛8 ="}', 1, '["初一","第6章 实数","动态随机"]', 'PROTOTYPE', 1, 2, 1);
INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (63, 'g7', 6, 21, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '下列各数中是无理数的是', '["0.3 循环","π","√9","22/7"]', '{"index":1}', '动态随机题型（每次闯关随机生成参数与选项）', 'c6_g0_2', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>{return mkg(\'下列各数中是无理数的是\',\'π\',[\'0.3 循环\',\'22/7\',\'√9\']);}","sampleStem":"下列各数中是无理数的是"}', 1, '["初一","第6章 实数","动态随机"]', 'PROTOTYPE', 1, 3, 1);
INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (64, 'g7', 6, 22, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '36 的平方根是', '["6","9","±6","−6"]', '{"index":2}', '动态随机题型（每次闯关随机生成参数与选项）', 'c6_g1_0', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>{const n=[16,36,64,100,144][R(0,4)];return mkg(n+\' 的平方根是\',\'±\'+Math.sqrt(n),[Math.sqrt(n)+\'\',\'−\'+Math.sqrt(n),String(n/4)])}","sampleStem":"36 的平方根是"}', 2, '["初一","第6章 实数","动态随机"]', 'PROTOTYPE', 1, 1, 1);
INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (65, 'g7', 6, 22, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '√18 在哪两个相邻整数之间', '["无法确定","5 与 6 之间","4 与 5 之间","3 与 4 之间"]', '{"index":2}', '动态随机题型（每次闯关随机生成参数与选项）', 'c6_g1_1', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>{const m=R(2,9);return mkg(\'√\'+(m*m+R(1,2*m-1))+\' 在哪两个相邻整数之间\',m+\' 与 \'+(m+1)+\' 之间\',[(m-1)+\' 与 \'+m+\' 之间\',(m+1)+\' 与 \'+(m+2)+\' 之间\',\'无法确定\'])}","sampleStem":"√18 在哪两个相邻整数之间"}', 2, '["初一","第6章 实数","动态随机"]', 'PROTOTYPE', 1, 2, 1);
INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (66, 'g7', 6, 22, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '实数与数轴上的点是一一对应的，这一说法', '["错误","正确","仅整数成立","仅正数成立"]', '{"index":1}', '动态随机题型（每次闯关随机生成参数与选项）', 'c6_g1_2', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>{return mkg(\'实数与数轴上的点是一一对应的，这一说法\',o=\'正确\',[\'正确\',\'错误\',\'仅正数成立\',\'仅整数成立\']);}","sampleStem":"实数与数轴上的点是一一对应的，这一说法"}', 2, '["初一","第6章 实数","动态随机"]', 'PROTOTYPE', 1, 3, 1);
INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (67, 'g7', 6, 23, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '化简 √45 =', '["9√5","3√25","1.7320508075688772√5","3√5"]', '{"index":3}', '动态随机题型（每次闯关随机生成参数与选项）', 'c6_g2_0', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>{const a=R(2,5),b=[2,3,5,6][R(0,3)];return mkg(\'化简 √\'+(a*a*b)+\' =\',a+\'√\'+b,[Math.sqrt(a)+\'√\'+b,(a*a)+\'√\'+b,a+\'√\'+(b*b)])}","sampleStem":"化简 √45 ="}', 3, '["初一","第6章 实数","动态随机"]', 'PROTOTYPE', 1, 1, 1);
INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (68, 'g7', 6, 23, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '计算 √2 × √3 =', '["6","√5","2√3","√6"]', '{"index":3}', '动态随机题型（每次闯关随机生成参数与选项）', 'c6_g2_1', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>{const a=[2,3,5][R(0,2)],b=[2,3,5][R(0,2)];return mkg(\'计算 √\'+a+\' × √\'+b+\' =\',\'√\'+(a*b),[a+\'√\'+b,\'√\'+(a+b),(a*b)+\'\'])}","sampleStem":"计算 √2 × √3 ="}', 3, '["初一","第6章 实数","动态随机"]', 'PROTOTYPE', 1, 2, 1);
INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (69, 'g7', 6, 23, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '使 √(x−8) 有意义的 x 的取值范围是', '["x≠8","x≤8","x≥8","x>8"]', '{"index":2}', '动态随机题型（每次闯关随机生成参数与选项）', 'c6_g2_2', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>{const c=R(2,9);return mkg(\'使 √(x−\'+c+\') 有意义的 x 的取值范围是\',\'x≥\'+c,[\'x>\'+c,\'x≤\'+c,\'x≠\'+c]);}","sampleStem":"使 √(x−8) 有意义的 x 的取值范围是"}', 3, '["初一","第6章 实数","动态随机"]', 'PROTOTYPE', 1, 3, 1);
INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (70, 'g7', 6, 24, 'STATIC', 'SINGLE_CHOICE', '已知 √a=2，∛b=3，则 a+b =', '["31","14","17","35"]', '{"index":0}', '', NULL, NULL, 4, '["初一","第6章 实数"]', 'PROTOTYPE', 1, 1, 1);
