INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (72, 'g7', 6, 24, 'STATIC', 'SINGLE_CHOICE', '若 √(x−1) + |y+2| = 0，则 x+y =', '["−1","1","−3","3"]', '{"index":0}', '', NULL, NULL, 4, '["初一","第6章 实数"]', 'PROTOTYPE', 1, 3, 1);
INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (73, 'g7', 7, 25, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '点 (-4,4) 在第几象限', '["第二象限","第三象限","第一象限","第四象限"]', '{"index":0}', '动态随机题型（每次闯关随机生成参数与选项）', 'c7_g0_0', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>{const a=[2,3,-4,-5][R(0,3)],b=[1,4,-2,-6][R(0,3)];const xq=a>0?(b>0?\'第一象限\':\'第四象限\'):(b>0?\'第二象限\':\'第三象限\');return mkg(\'点 (\'+a+\',\'+b+\') 在第几象限\',xq,[\'第一象限\',\'第二象限\',\'第三象限\',\'第四象限\'].filter(x=>x!==xq));}","sampleStem":"点 (-4,4) 在第几象限"}', 1, '["初一","第7章 平面直角坐标系","动态随机"]', 'PROTOTYPE', 1, 1, 1);
INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (74, 'g7', 7, 25, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '点 (2,4) 关于 x 轴对称的点是', '["−2,−4","−2,4","(2,−4)","(4,2)"]', '{"index":2}', '动态随机题型（每次闯关随机生成参数与选项）', 'c7_g0_1', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>{const a=R(1,5),b=R(1,5);return mkg(\'点 (\'+a+\',\'+b+\') 关于 x 轴对称的点是\',\'(\'+a+\',−\'+b+\')\',[(\'−\'+a+\',\'+b),(\'−\'+a+\',−\'+b),(\'(\'+b+\',\'+a+\')\')])}","sampleStem":"点 (2,4) 关于 x 轴对称的点是"}', 1, '["初一","第7章 平面直角坐标系","动态随机"]', 'PROTOTYPE', 1, 2, 1);
INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (75, 'g7', 7, 25, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '点 (1,4) 向右平移 5 个单位得到的点是', '["(6,4)","(1,-1)","(-4,4)","(1,9)"]', '{"index":0}', '动态随机题型（每次闯关随机生成参数与选项）', 'c7_g0_2', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>{const a=R(1,5),b=R(1,5),k=R(2,5);return mkg(\'点 (\'+a+\',\'+b+\') 向右平移 \'+k+\' 个单位得到的点是\',(\'(\')+(a+k)+\',\'+b+\')\',[\'(\'+(a-k)+\',\'+b+\')\',\'(\'+a+\',\'+(b+k)+\')\',\'(\'+a+\',\'+(b-k)+\')\']);}","sampleStem":"点 (1,4) 向右平移 5 个单位得到的点是"}', 1, '["初一","第7章 平面直角坐标系","动态随机"]', 'PROTOTYPE', 1, 3, 1);
INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (76, 'g7', 7, 26, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '点 (5,2) 关于 y 轴对称的点是', '["(−5,2)","(5,−2)","(2,5)","−5,−2"]', '{"index":0}', '动态随机题型（每次闯关随机生成参数与选项）', 'c7_g1_0', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>{const a=R(1,5),b=R(1,5);return mkg(\'点 (\'+a+\',\'+b+\') 关于 y 轴对称的点是\',\'(−\'+a+\',\'+b+\')\',[(\'(\'+a+\',−\'+b+\')\'),(\'−\'+a+\',−\'+b),(\'(\'+b+\',\'+a+\')\')])}","sampleStem":"点 (5,2) 关于 y 轴对称的点是"}', 2, '["初一","第7章 平面直角坐标系","动态随机"]', 'PROTOTYPE', 1, 1, 1);
INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (77, 'g7', 7, 26, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '点 (3,1) 向上平移 2 个单位得到的点是', '["(3,3)","(1,1)","(3,-1)","(5,1)"]', '{"index":0}', '动态随机题型（每次闯关随机生成参数与选项）', 'c7_g1_1', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>{const a=R(1,5),b=R(1,5),k=R(2,5);return mkg(\'点 (\'+a+\',\'+b+\') 向上平移 \'+k+\' 个单位得到的点是\',\'(\'+a+\',\'+(b+k)+\')\',[\'(\'+(a+k)+\',\'+b+\')\',\'(\'+a+\',\'+(b-k)+\')\',\'(\'+(a-k)+\',\'+b+\')\'])}","sampleStem":"点 (3,1) 向上平移 2 个单位得到的点是"}', 2, '["初一","第7章 平面直角坐标系","动态随机"]', 'PROTOTYPE', 1, 2, 1);
INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (78, 'g7', 7, 26, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '点 (9,0) 与点 (0,12) 之间的距离是', '["21","3","15","108"]', '{"index":2}', '动态随机题型（每次闯关随机生成参数与选项）', 'c7_g1_2', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>{const p=[[3,4],[6,8],[5,12],[9,12]][R(0,3)];return mkg(\'点 (\'+p[0]+\',0) 与点 (0,\'+p[1]+\') 之间的距离是\',String(Math.hypot(p[0],p[1])),[String(p[0]+p[1]),String(Math.abs(p[0]-p[1])),String(p[0]*p[1])]);}","sampleStem":"点 (9,0) 与点 (0,12) 之间的距离是"}', 2, '["初一","第7章 平面直角坐标系","动态随机"]', 'PROTOTYPE', 1, 3, 1);
