INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (80, 'g7', 7, 27, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '点 (4,4) 到 x 轴的距离是', '["5","16","4","8"]', '{"index":2}', '动态随机题型（每次闯关随机生成参数与选项）', 'c7_g2_1', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>{const a=R(1,4),b=R(1,4);return mkg(\'点 (\'+a+\',\'+b+\') 到 x 轴的距离是\',String(b),[String(a),String(a+b),String(a*b)])}","sampleStem":"点 (4,4) 到 x 轴的距离是"}', 3, '["初一","第7章 平面直角坐标系","动态随机"]', 'PROTOTYPE', 1, 2, 1);
