INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (85, 'g7', 8, 29, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '方程组 { 2x+1y=12, 1x+3y=26 } 的解是', '["x=2, y=8","x=3, y=8","x=2, y=7","x=8, y=2"]', '{"index":0}', '动态随机题型（每次闯关随机生成参数与选项）', 'c8_g0_0', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>{const x=R(2,8),y=R(2,9),a=R(1,3),b=R(1,3),c=R(1,3),d=R(1,3);return mkg(\'方程组 { \'+a+\'x+\'+b+\'y=\'+(a*x+b*y)+\', \'+c+\'x+\'+d+\'y=\'+(c*x+d*y)+\' } 的解是\',\'x=\'+x+\', y=\'+y,[\'x=\'+y+\', y=\'+x,\'x=\'+(x+1)+\', y=\'+y,\'x=\'+x+\', y=\'+(y-1)])}","sampleStem":"方程组 { 2x+1y=12, 1x+3y=26 } 的解是"}', 1, '["初一","第8章 二元一次方程组","动态随机"]', 'PROTOTYPE', 1, 1, 1);
INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (86, 'g7', 8, 29, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '若 x+y=16，x−y=-2，则 x =', '["-2","9","16","7"]', '{"index":3}', '动态随机题型（每次闯关随机生成参数与选项）', 'c8_g0_1', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>{const x=R(2,8),y=R(2,9);return mkg(\'若 x+y=\'+(x+y)+\'，x−y=\'+(x-y)+\'，则 x =\',String(x),[String(y),String(x+y),String(x-y)])}","sampleStem":"若 x+y=16，x−y=-2，则 x ="}', 1, '["初一","第8章 二元一次方程组","动态随机"]', 'PROTOTYPE', 1, 2, 1);
INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (87, 'g7', 8, 29, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '下列是二元一次方程的是', '["x²+y=3","2x+y=3","x²+y²=1","x+1/y=2"]', '{"index":1}', '动态随机题型（每次闯关随机生成参数与选项）', 'c8_g0_2', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>{return mkg(\'下列是二元一次方程的是\',\'2x+y=3\',[\'x²+y=3\',\'x+1/y=2\',\'x²+y²=1\']);}","sampleStem":"下列是二元一次方程的是"}', 1, '["初一","第8章 二元一次方程组","动态随机"]', 'PROTOTYPE', 1, 3, 1);
INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (88, 'g7', 8, 30, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '已知 { x+y=10, 2x+y=15 }，则 y =', '["4","10","5","6"]', '{"index":2}', '动态随机题型（每次闯关随机生成参数与选项）', 'c8_g1_0', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>{const x=R(2,8),y=R(2,9);return mkg(\'已知 { x+y=\'+(x+y)+\', 2x+y=\'+(2*x+y)+\' }，则 y =\',String(y),[String(x),String(x+y),String(y+1)])}","sampleStem":"已知 { x+y=10, 2x+y=15 }，则 y ="}', 2, '["初一","第8章 二元一次方程组","动态随机"]', 'PROTOTYPE', 1, 1, 1);
INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (89, 'g7', 8, 30, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '鸡兔同笼：共 9 个头，26 只脚，则鸡有', '["4","6","9","5"]', '{"index":3}', '动态随机题型（每次闯关随机生成参数与选项）', 'c8_g1_1', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>{const x=R(2,7),y=R(2,9);return mkg(\'鸡兔同笼：共 \'+(x+y)+\' 个头，\'+(2*x+4*y)+\' 只脚，则鸡有\',String(x),[String(y),String(x+y),String(x-1)])}","sampleStem":"鸡兔同笼：共 9 个头，26 只脚，则鸡有"}', 2, '["初一","第8章 二元一次方程组","动态随机"]', 'PROTOTYPE', 1, 2, 1);
INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (90, 'g7', 8, 30, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '若 3x−2y=3，用含 x 的式子表示 y，得 y =', '["(3x+3)/2","3x/2−3","(3x−3)/2","(2y+3)/3"]', '{"index":2}', '动态随机题型（每次闯关随机生成参数与选项）', 'c8_g1_2', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>{const x=R(2,8),y=R(2,9),a=R(2,3);return mkg(\'若 3x−2y=\'+(3*x-2*y)+\'，用含 x 的式子表示 y，得 y =\',\'(\'+(3)+\'x−\'+(3*x-2*y)+\')/2\',[\'(3x+\'+(3*x-2*y)+\')/2\',\'3x/2−\'+(3*x-2*y),\'(2y+\'+(3*x-2*y)+\')/3\']);}","sampleStem":"若 3x−2y=3，用含 x 的式子表示 y，得 y ="}', 2, '["初一","第8章 二元一次方程组","动态随机"]', 'PROTOTYPE', 1, 3, 1);
INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (91, 'g7', 8, 31, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '甲种本每本 2 元、乙种本每本 1 元，买两种共 8 本花了 12 元，则甲种买了', '["4","3","5","8"]', '{"index":0}', '动态随机题型（每次闯关随机生成参数与选项）', 'c8_g2_0', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>{const x=R(3,9),y=R(2,9),p=R(1,5),q=R(1,5);return mkg(\'甲种本每本 \'+p+\' 元、乙种本每本 \'+q+\' 元，买两种共 \'+(x+y)+\' 本花了 \'+(p*x+q*y)+\' 元，则甲种买了\',String(x),[String(y),String(x+y),String(x-1)])}","sampleStem":"甲种本每本 2 元、乙种本每本 1 元，买两种共 8 本花了 12 元，则甲种买了"}', 3, '["初一","第8章 二元一次方程组","动态随机"]', 'PROTOTYPE', 1, 1, 1);
INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (92, 'g7', 8, 31, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '方程组 { x+y=12, x·y=36 } 的解是', '["x=6, y=6+1","x=6, y=6","x=7, y=5","x=5, y=7"]', '{"index":1}', '动态随机题型（每次闯关随机生成参数与选项）', 'c8_g2_1', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>{const x=R(2,8),y=R(2,9);return mkg(\'方程组 { x+y=\'+(x+y)+\', x·y=\'+(x*y)+\' } 的解是\',\'x=\'+x+\', y=\'+y,[\'x=\'+y+\', y=\'+x,\'x=\'+(x+1)+\', y=\'+(y-1),\'x=\'+(x-1)+\', y=\'+(y+1)])}","sampleStem":"方程组 { x+y=12, x·y=36 } 的解是"}', 3, '["初一","第8章 二元一次方程组","动态随机"]', 'PROTOTYPE', 1, 2, 1);
INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (93, 'g7', 8, 31, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '一个两位数，十位数字为 5，个位数字为 6，把两个数字对调后，新数比原数小 -9？结论：差一定是', '["9","11","-1","一定是 9"]', '{"index":0}', '动态随机题型（每次闯关随机生成参数与选项）', 'c8_g2_2', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>{const x=R(3,9),y=R(3,9);return mkg(\'一个两位数，十位数字为 \'+x+\'，个位数字为 \'+y+\'，把两个数字对调后，新数比原数小 \'+(10*x+y-(10*y+x))+\'？结论：差一定是\',String(9*Math.abs(x-y)),[String(x+y),String(x-y),\'一定是 9\']);}","sampleStem":"一个两位数，十位数字为 5，个位数字为 6，把两个数字对调后，新数比原数小 -9？结论：差一定是"}', 3, '["初一","第8章 二元一次方程组","动态随机"]', 'PROTOTYPE', 1, 3, 1);
