INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (95, 'g7', 8, 32, 'STATIC', 'SINGLE_CHOICE', '若 { 2x+y=5m, x−y=m } 的解满足 x+y=12，则 m =', '["4","3","5","6"]', '{"index":0}', '', NULL, NULL, 4, '["初一","第8章 二元一次方程组"]', 'PROTOTYPE', 1, 2, 1);
INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (96, 'g7', 8, 32, 'STATIC', 'SINGLE_CHOICE', '某车队用大车与小车运货，2 大 3 小一次运 15.5 吨，5 大 6 小一次运 35 吨，则 1 大车一次运', '["4 吨","3.5 吨","4.5 吨","5 吨"]', '{"index":0}', '', NULL, NULL, 4, '["初一","第8章 二元一次方程组"]', 'PROTOTYPE', 1, 3, 1);
INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (97, 'g7', 9, 33, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '解不等式 3x − 3 > 0', '["x > 1","x < 3","x < 1","x > 3"]', '{"index":0}', '动态随机题型（每次闯关随机生成参数与选项）', 'c9_g0_0', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>{const a=R(2,5),k=R(1,6);return mkg(\'解不等式 \'+a+\'x − \'+(a*k)+\' > 0\',\'x > \'+k,[\'x < \'+k,\'x > \'+(a*k),\'x < \'+(a*k)])}","sampleStem":"解不等式 3x − 3 > 0"}', 1, '["初一","第9章 不等式与不等式组","动态随机"]', 'PROTOTYPE', 1, 1, 1);
INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (98, 'g7', 9, 33, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '解不等式 5x + 25 ≤ 0', '["x ≥ −5","x ≤ −5","x < −5","x ≤ 5"]', '{"index":1}', '动态随机题型（每次闯关随机生成参数与选项）', 'c9_g0_1', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>{const a=R(2,5),k=R(1,6);return mkg(\'解不等式 \'+a+\'x + \'+a*k+\' ≤ 0\',\'x ≤ −\'+k,[\'x ≥ −\'+k,\'x ≤ \'+k,\'x < −\'+k])}","sampleStem":"解不等式 5x + 25 ≤ 0"}', 1, '["初一","第9章 不等式与不等式组","动态随机"]', 'PROTOTYPE', 1, 2, 1);
INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (99, 'g7', 9, 33, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '不等式的基本性质：两边同时乘以同一个负数，不等号方向', '["不变","变大","改变","无法确定"]', '{"index":2}', '动态随机题型（每次闯关随机生成参数与选项）', 'c9_g0_2', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>{return mkg(\'不等式的基本性质：两边同时乘以同一个负数，不等号方向\',\'改变\',[\'不变\',\'变大\',\'无法确定\']);}","sampleStem":"不等式的基本性质：两边同时乘以同一个负数，不等号方向"}', 1, '["初一","第9章 不等式与不等式组","动态随机"]', 'PROTOTYPE', 1, 3, 1);
INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (100, 'g7', 9, 34, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '解不等式 −2x + 10 > 0', '["x < −5","x > 5","x < 5","x > −5"]', '{"index":2}', '动态随机题型（每次闯关随机生成参数与选项）', 'c9_g1_0', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>{const a=R(2,5),k=R(1,6);return mkg(\'解不等式 −\'+a+\'x + \'+(a*k)+\' > 0\',\'x < \'+k,[\'x > \'+k,\'x < −\'+k,\'x > −\'+k])}","sampleStem":"解不等式 −2x + 10 > 0"}', 2, '["初一","第9章 不等式与不等式组","动态随机"]', 'PROTOTYPE', 1, 1, 1);
INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (101, 'g7', 9, 34, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '不等式 4x > 9 的解中，最小整数是', '["2","8","4","3"]', '{"index":3}', '动态随机题型（每次闯关随机生成参数与选项）', 'c9_g1_1', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>{const a=R(2,4),k=R(1,4);return mkg(\'不等式 \'+a+\'x > \'+(a*k+1)+\' 的解中，最小整数是\',String(k+1),[String(k),String(k+2),String(a*k)])}","sampleStem":"不等式 4x > 9 的解中，最小整数是"}', 2, '["初一","第9章 不等式与不等式组","动态随机"]', 'PROTOTYPE', 1, 2, 1);
INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (102, 'g7', 9, 34, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '解集为 x < 5 的不等式可以是', '["-4x < -20","5x < 20","4x < 20","4x > 20"]', '{"index":2}', '动态随机题型（每次闯关随机生成参数与选项）', 'c9_g1_2', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>{const a=R(2,4),k=R(1,5);return mkg(\'解集为 x < \'+k+\' 的不等式可以是\',(a)+\'x < \'+(a*k),[a+\'x > \'+(a*k),(-a)+\'x < \'+(-a*k),(a+1)+\'x < \'+(a*k)]);}","sampleStem":"解集为 x < 5 的不等式可以是"}', 2, '["初一","第9章 不等式与不等式组","动态随机"]', 'PROTOTYPE', 1, 3, 1);
INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (103, 'g7', 9, 35, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '不等式组 { x > −4, x < 4 } 的解集是', '["空集","x > −4","−4 < x < 4","x > 4 或 x < −4"]', '{"index":2}', '动态随机题型（每次闯关随机生成参数与选项）', 'c9_g2_0', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>{const k=R(2,5);return mkg(\'不等式组 { x > −\'+k+\', x < \'+k+\' } 的解集是\',\'−\'+k+\' < x < \'+k,[\'x > \'+k+\' 或 x < −\'+k,\'空集\',\'x > −\'+k])}","sampleStem":"不等式组 { x > −4, x < 4 } 的解集是"}', 3, '["初一","第9章 不等式与不等式组","动态随机"]', 'PROTOTYPE', 1, 1, 1);
INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (104, 'g7', 9, 35, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '不等式组 { x > 2, x > 4 } 的解集是', '["x > 4","x > 2","x < 4","3 < x < 4"]', '{"index":0}', '动态随机题型（每次闯关随机生成参数与选项）', 'c9_g2_1', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>{const a=R(2,5);return mkg(\'不等式组 { x > \'+a+\', x > \'+(a+2)+\' } 的解集是\',\'x > \'+(a+2),[\'x > \'+a,\'x < \'+(a+2),(a+1)+\' < x < \'+(a+2)])}","sampleStem":"不等式组 { x > 2, x > 4 } 的解集是"}', 3, '["初一","第9章 不等式与不等式组","动态随机"]', 'PROTOTYPE', 1, 2, 1);
INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (105, 'g7', 9, 35, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '不等式组 { x ≥ 4, x ≤ 5 } 的解集是', '["4 ≤ x ≤ 5","x ≤ 5","空集","x > 4"]', '{"index":0}', '动态随机题型（每次闯关随机生成参数与选项）', 'c9_g2_2', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>{const k=R(2,5);return mkg(\'不等式组 { x ≥ \'+k+\', x ≤ \'+(k+1)+\' } 的解集是\',k+\' ≤ x ≤ \'+(k+1),[\'空集\',\'x > \'+k,\'x ≤ \'+(k+1)]);}","sampleStem":"不等式组 { x ≥ 4, x ≤ 5 } 的解集是"}', 3, '["初一","第9章 不等式与不等式组","动态随机"]', 'PROTOTYPE', 1, 3, 1);
