INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (109, 'g7', 10, 37, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '了解一批灯泡的使用寿命，适合采用的调查方式是', '["抽样调查","全面调查","普查","访问调查"]', '{"index":0}', '动态随机题型（每次闯关随机生成参数与选项）', 'c10_g0_0', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>mkg(\'了解一批灯泡的使用寿命，适合采用的调查方式是\',\'抽样调查\',[\'全面调查\',\'普查\',\'访问调查\',\'逐一测试\'])","sampleStem":"了解一批灯泡的使用寿命，适合采用的调查方式是"}', 1, '["初一","第10章 数据的收集整理与描述","动态随机"]', 'PROTOTYPE', 1, 1, 1);
INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (110, 'g7', 10, 37, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '考察全体对象的调查叫做', '["抽样调查","随机调查","问卷调查","全面调查"]', '{"index":3}', '动态随机题型（每次闯关随机生成参数与选项）', 'c10_g0_1', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>mkg(\'考察全体对象的调查叫做\',\'全面调查\',[\'抽样调查\',\'问卷调查\',\'随机调查\',\'统计调查\'])","sampleStem":"考察全体对象的调查叫做"}', 1, '["初一","第10章 数据的收集整理与描述","动态随机"]', 'PROTOTYPE', 1, 2, 1);
INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (111, 'g7', 10, 37, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '频数分布中，某组频数为 36，总数为 144，则该组频率是', '["0.75","0.2","0.5","0.25"]', '{"index":3}', '动态随机题型（每次闯关随机生成参数与选项）', 'c10_g0_2', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>{const n=R(20,50);return mkg(\'频数分布中，某组频数为 \'+n+\'，总数为 \'+(n*4)+\'，则该组频率是\',\'0.25\',[\'0.2\',\'0.5\',\'0.75\']);}","sampleStem":"频数分布中，某组频数为 36，总数为 144，则该组频率是"}', 1, '["初一","第10章 数据的收集整理与描述","动态随机"]', 'PROTOTYPE', 1, 3, 1);
INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (112, 'g7', 10, 38, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '某组频数为 18，频率为 3/21 的分母是 21，则总数是', '["21","19","18","4"]', '{"index":0}', '动态随机题型（每次闯关随机生成参数与选项）', 'c10_g1_0', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>{const t=R(2,5),f=R(3,7);return mkg(\'某组频数为 \'+(t*f)+\'，频率为 \'+t+\'/\'+(t*f+t)+ \' 的分母是 \'+(t*f+t)+\'，则总数是\',(t*f+t)+\'\',[t*f+\'\',(t*f+1)+\'\',(t+1)+\'\'])}","sampleStem":"某组频数为 18，频率为 3/21 的分母是 21，则总数是"}', 2, '["初一","第10章 数据的收集整理与描述","动态随机"]', 'PROTOTYPE', 1, 1, 1);
INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (113, 'g7', 10, 38, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '反映数据变化趋势的统计图是', '["频数直方图","折线图","条形图","扇形图"]', '{"index":1}', '动态随机题型（每次闯关随机生成参数与选项）', 'c10_g1_1', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>mkg(\'反映数据变化趋势的统计图是\',\'折线图\',[\'条形图\',\'扇形图\',\'频数直方图\',\'表格\'])","sampleStem":"反映数据变化趋势的统计图是"}', 2, '["初一","第10章 数据的收集整理与描述","动态随机"]', 'PROTOTYPE', 1, 2, 1);
INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (114, 'g7', 10, 38, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '反映各部分占总体的百分比，适合用', '["扇形统计图","折线图","条形图","频数直方图"]', '{"index":0}', '动态随机题型（每次闯关随机生成参数与选项）', 'c10_g1_2', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>{return mkg(\'反映各部分占总体的百分比，适合用\',\'扇形统计图\',[\'折线图\',\'条形图\',\'频数直方图\',\'茎叶图\']);}","sampleStem":"反映各部分占总体的百分比，适合用"}', 2, '["初一","第10章 数据的收集整理与描述","动态随机"]', 'PROTOTYPE', 1, 3, 1);
INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (115, 'g7', 10, 39, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '扇形统计图中两部分圆心角分别为 144° 与 216°，则两部分的频率之比是', '["2 : 3","5 : 2","4 : 9","1 : 1"]', '{"index":0}', '动态随机题型（每次闯关随机生成参数与选项）', 'c10_g2_0', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>{const p=[[1,2],[1,3],[2,3],[1,5],[3,5],[4,5],[5,7]][R(0,6)];const a=p[0],b=p[1];return mkg(\'扇形统计图中两部分圆心角分别为 \'+(360*a/(a+b))+\'° 与 \'+(360*b/(a+b))+\'°，则两部分的频率之比是\',a+\' : \'+b,[(a+b)+\' : \'+a,\'1 : 1\',(a*a)+\' : \'+(b*b)])}","sampleStem":"扇形统计图中两部分圆心角分别为 144° 与 216°，则两部分的频率之比是"}', 3, '["初一","第10章 数据的收集整理与描述","动态随机"]', 'PROTOTYPE', 1, 1, 1);
