INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (121, 'g8', 11, 41, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '△ABC 中 ∠A=45°、∠B=63°，则 ∠C =', '["72°+1","82°","72°","108°"]', '{"index":2}', '动态随机题型（每次闯关随机生成参数与选项）', 'c11_g0_0', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>{const a=R(30,70),b=R(30,80);const c=180-a-b;return mkg(\'△ABC 中 ∠A=\'+a+\'°、∠B=\'+b+\'°，则 ∠C =\',c+\'°\',[(180-c)+\'°\',(a+b)+\'°\',(c+10)+\'°\'])}","sampleStem":"△ABC 中 ∠A=45°、∠B=63°，则 ∠C ="}', 1, '["初二","第11章 三角形","动态随机"]', 'PROTOTYPE', 1, 1, 1);
INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (122, 'g8', 11, 41, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '5 边形的内角和是', '["540°","360°","900°","720°"]', '{"index":0}', '动态随机题型（每次闯关随机生成参数与选项）', 'c11_g0_1', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>{const n=R(5,8);return mkg((n)+\' 边形的内角和是\',((n-2)*180)+\'°\',[(n*180)+\'°\',((n-1)*180)+\'°\',(360)+\'°\'])}","sampleStem":"5 边形的内角和是"}', 1, '["初二","第11章 三角形","动态随机"]', 'PROTOTYPE', 1, 2, 1);
INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (123, 'g8', 11, 41, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '△ABC 中 ∠B=37°、∠C=37°，则 ∠A 的外角等于', '["0°","74°","106°","37°"]', '{"index":1}', '动态随机题型（每次闯关随机生成参数与选项）', 'c11_g0_2', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>{const x=R(30,60),y=R(30,60);return mkg(\'△ABC 中 ∠B=\'+x+\'°、∠C=\'+y+\'°，则 ∠A 的外角等于\',(x+y)+\'°\',[Math.abs(x-y)+\'°\',(180-x-y)+\'°\',x+\'°\']);}","sampleStem":"△ABC 中 ∠B=37°、∠C=37°，则 ∠A 的外角等于"}', 1, '["初二","第11章 三角形","动态随机"]', 'PROTOTYPE', 1, 3, 1);
INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (124, 'g8', 11, 42, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '下列长度的三条线段能构成三角形的是', '["2, 9, 12","2, 9, 8","2, 9, 11","2, 9, 7"]', '{"index":1}', '动态随机题型（每次闯关随机生成参数与选项）', 'c11_g1_0', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>{const a=R(2,9),b=R(2,9),c=R(Math.abs(a-b)+1,a+b-1);return mkg(\'下列长度的三条线段能构成三角形的是\',a+\', \'+b+\', \'+c,[a+\', \'+b+\', \'+(a+b),a+\', \'+b+\', \'+Math.abs(a-b),a+\', \'+b+\', \'+(a+b+1)])}","sampleStem":"下列长度的三条线段能构成三角形的是"}', 2, '["初二","第11章 三角形","动态随机"]', 'PROTOTYPE', 1, 1, 1);
INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (125, 'g8', 11, 42, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '等腰三角形腰长 3、底长 1，则周长为', '["8","7","2","6"]', '{"index":1}', '动态随机题型（每次闯关随机生成参数与选项）', 'c11_g1_1', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>{const w=R(3,9),d=R(1,w-1);return mkg(\'等腰三角形腰长 \'+w+\'、底长 \'+d+\'，则周长为\',(2*w+d)+\'\',[2*d+\'\',(2*w)+\'\',(2*w+d+1)+\'\'])}","sampleStem":"等腰三角形腰长 3、底长 1，则周长为"}', 2, '["初二","第11章 三角形","动态随机"]', 'PROTOTYPE', 1, 2, 1);
INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (126, 'g8', 11, 42, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '等腰三角形顶角为 28°，则底角为', '["76°","28°","62°","152°"]', '{"index":0}', '动态随机题型（每次闯关随机生成参数与选项）', 'c11_g1_2', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>{const a=2*R(10,40);const x=(180-a)/2;return mkg(\'等腰三角形顶角为 \'+a+\'°，则底角为\',x+\'°\',[a+\'°\',(90-a)+\'°\',(180-a)+\'°\']);}","sampleStem":"等腰三角形顶角为 28°，则底角为"}', 2, '["初二","第11章 三角形","动态随机"]', 'PROTOTYPE', 1, 3, 1);
INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (127, 'g8', 11, 43, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '正 8 边形每个外角等于', '["35°","22.5°","40°","45°"]', '{"index":3}', '动态随机题型（每次闯关随机生成参数与选项）', 'c11_g2_0', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>{const n=R(5,9);return mkg(\'正 \'+n+\' 边形每个外角等于\',(360/n)+\'°\',[(180/n)+\'°\',(360/(n+1))+\'°\',(360/n-10)+\'°\'])}","sampleStem":"正 8 边形每个外角等于"}', 3, '["初二","第11章 三角形","动态随机"]', 'PROTOTYPE', 1, 1, 1);
INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (128, 'g8', 11, 43, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '△ABC 中 ∠A:∠B:∠C = 2:3:4，则 ∠C =', '["60°","80°","100°","40°"]', '{"index":1}', '动态随机题型（每次闯关随机生成参数与选项）', 'c11_g2_1', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>{const p=[[2,3,4],[1,2,3],[1,1,2],[2,2,1],[3,4,5]][R(0,4)];const t=180/(p[0]+p[1]+p[2]);const A=p[0]*t,B=p[1]*t,C=p[2]*t;return mkg(\'△ABC 中 ∠A:∠B:∠C = \'+p[0]+\':\'+p[1]+\':\'+p[2]+\'，则 ∠C =\',C+\'°\',[A+\'°\',B+\'°\',(180-C)+\'°\'])}","sampleStem":"△ABC 中 ∠A:∠B:∠C = 2:3:4，则 ∠C ="}', 3, '["初二","第11章 三角形","动态随机"]', 'PROTOTYPE', 1, 2, 1);
INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (129, 'g8', 11, 43, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '9 边形共有对角线', '["9 条","81 条","31.5 条","27 条"]', '{"index":3}', '动态随机题型（每次闯关随机生成参数与选项）', 'c11_g2_2', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>{const n=R(6,10);return mkg(n+\' 边形共有对角线\',(n*(n-3)/2)+\' 条\',[n+\' 条\',(n*(n-2)/2)+\' 条\',(n*n)+\' 条\']);}","sampleStem":"9 边形共有对角线"}', 3, '["初二","第11章 三角形","动态随机"]', 'PROTOTYPE', 1, 3, 1);
