INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (150, 'g8', 13, 50, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '点 (2,3) 关于直线 x=1 对称的点是', '["(2,−3)","(−2,3)","(0,3)","(−1,3)"]', '{"index":2}', '动态随机题型（每次闯关随机生成参数与选项）', 'c13_g1_2', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>{return mkg(\'点 (2,3) 关于直线 x=1 对称的点是\',\'(0,3)\',[\'(−2,3)\',\'(2,−3)\',\'(−1,3)\']);}","sampleStem":"点 (2,3) 关于直线 x=1 对称的点是"}', 2, '["初二","第13章 轴对称","动态随机"]', 'PROTOTYPE', 1, 3, 1);
INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (151, 'g8', 13, 51, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '等腰三角形腰长 4，底长 6，则其周长为', '["12","14","8","16"]', '{"index":1}', '动态随机题型（每次闯关随机生成参数与选项）', 'c13_g2_0', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>{const w=R(3,9);return mkg(\'等腰三角形腰长 \'+w+\'，底长 \'+(w+2)+\'，则其周长为\',(3*w+2)+\'\',[2*w+\'\',(3*w)+\'\',(3*w+4)+\'\'])}","sampleStem":"等腰三角形腰长 4，底长 6，则其周长为"}', 3, '["初二","第13章 轴对称","动态随机"]', 'PROTOTYPE', 1, 1, 1);
INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (152, 'g8', 13, 51, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '等腰三角形一腰上的高与另一腰的夹角为 30°，且顶角为钝角，则顶角 =', '["145°","55°","35°","70°"]', '{"index":0}', '动态随机题型（每次闯关随机生成参数与选项）', 'c13_g2_1', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>{const a=R(40,60);return mkg(\'等腰三角形一腰上的高与另一腰的夹角为 30°，且顶角为钝角，则顶角 =\',(90+a)+\'°\',[(90-a)+\'°\',a+\'°\',(180-2*a)+\'°\'])}","sampleStem":"等腰三角形一腰上的高与另一腰的夹角为 30°，且顶角为钝角，则顶角 ="}', 3, '["初二","第13章 轴对称","动态随机"]', 'PROTOTYPE', 1, 2, 1);
INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (153, 'g8', 13, 51, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '∠MON=40°，P 为角平分线上一点，PE⊥OM，PF⊥ON，PE=5，则 PF =', '["5","10","无法确定","2.5"]', '{"index":0}', '动态随机题型（每次闯关随机生成参数与选项）', 'c13_g2_2', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>{return mkg(\'∠MON=40°，P 为角平分线上一点，PE⊥OM，PF⊥ON，PE=5，则 PF =\',\'5\',[\'10\',\'2.5\',\'无法确定\']);}","sampleStem":"∠MON=40°，P 为角平分线上一点，PE⊥OM，PF⊥ON，PE=5，则 PF ="}', 3, '["初二","第13章 轴对称","动态随机"]', 'PROTOTYPE', 1, 3, 1);
