INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (157, 'g8', 14, 53, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '计算 a^6 · a^4 =', '["a^24","a^6","a^10","a^11"]', '{"index":2}', '动态随机题型（每次闯关随机生成参数与选项）', 'c14_g0_0', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>{const m=R(2,6),n=R(2,6);return mkg(\'计算 a^\'+m+\' · a^\'+n+\' =\',\'a^\'+(m+n),[\'a^\'+(m*n),\'a^\'+Math.max(m,n),\'a^\'+(m+n+1)])}","sampleStem":"计算 a^6 · a^4 ="}', 1, '["初二","第14章 整式的乘法与因式分解","动态随机"]', 'PROTOTYPE', 1, 1, 1);
INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (158, 'g8', 14, 53, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '计算 (a^5)^2 =', '["a^7","a^8","a^5","a^10"]', '{"index":3}', '动态随机题型（每次闯关随机生成参数与选项）', 'c14_g0_1', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>{const m=R(2,5),n=R(2,5);return mkg(\'计算 (a^\'+m+\')^\'+n+\' =\',\'a^\'+(m*n),[\'a^\'+(m+n),\'a^\'+(m+n+1),\'a^\'+Math.max(m,n)])}","sampleStem":"计算 (a^5)^2 ="}', 1, '["初二","第14章 整式的乘法与因式分解","动态随机"]', 'PROTOTYPE', 1, 2, 1);
INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (159, 'g8', 14, 53, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '计算 (2a)^4 =', '["2^3a^4","a^8","2^4 a^4","2a^4"]', '{"index":2}', '动态随机题型（每次闯关随机生成参数与选项）', 'c14_g0_2', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>{const n=R(2,5);return mkg(\'计算 (2a)^\'+n+\' =\',\'2^\'+n+\' a^\'+n,[2+\'a^\'+n,\'2^\'+(n-1)+\'a^\'+n,\'a^\'+(2*n)])}","sampleStem":"计算 (2a)^4 ="}', 1, '["初二","第14章 整式的乘法与因式分解","动态随机"]', 'PROTOTYPE', 1, 3, 1);
INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (160, 'g8', 14, 54, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '计算 (x+6)(x−6) =', '["x²−12x+36","x²−36","x²+36","x²−6"]', '{"index":1}', '动态随机题型（每次闯关随机生成参数与选项）', 'c14_g1_0', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>{const p=R(2,9);return mkg(\'计算 (x+\'+p+\')(x−\'+p+\') =\',\'x²−\'+(p*p),[\'x²+\'+(p*p),\'x²−\'+(2*p)+\'x+\'+(p*p),\'x²−\'+p])}","sampleStem":"计算 (x+6)(x−6) ="}', 2, '["初二","第14章 整式的乘法与因式分解","动态随机"]', 'PROTOTYPE', 1, 1, 1);
