INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (162, 'g8', 14, 54, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '计算 (x+6)(x+3) =', '["x²−9x+18","x²+18x+9","x²+9x+18","x²+9x+9"]', '{"index":2}', '动态随机题型（每次闯关随机生成参数与选项）', 'c14_g1_2', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>{const a=R(2,6),b=R(2,6);return mkg(\'计算 (x+\'+a+\')(x+\'+b+\') =\',\'x²+\'+(a+b)+\'x+\'+(a*b),[\'x²+\'+(a*b)+\'x+\'+(a+b),\'x²+\'+(a+b)+\'x+\'+(a+b),\'x²−\'+(a+b)+\'x+\'+(a*b)]);}","sampleStem":"计算 (x+6)(x+3) ="}', 2, '["初二","第14章 整式的乘法与因式分解","动态随机"]', 'PROTOTYPE', 1, 3, 1);
INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (163, 'g8', 14, 55, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '因式分解 x²−64 =', '["(x+8)²","x(x−8)","(x−8)²","(x+8)(x−8)"]', '{"index":3}', '动态随机题型（每次闯关随机生成参数与选项）', 'c14_g2_0', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>{const p=R(2,9);return mkg(\'因式分解 x²−\'+(p*p)+\' =\',\'(x+\'+p+\')(x−\'+p+\')\',[\'(x+\'+p+\')²\',\'(x−\'+p+\')²\',\'x(x−\'+p+\')\'])}","sampleStem":"因式分解 x²−64 ="}', 3, '["初二","第14章 整式的乘法与因式分解","动态随机"]', 'PROTOTYPE', 1, 1, 1);
INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (164, 'g8', 14, 55, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '因式分解 x²+10x+25 =', '["(x+5)²","(x−5)²","(x+5)(x−5)","x(x+10)"]', '{"index":0}', '动态随机题型（每次闯关随机生成参数与选项）', 'c14_g2_1', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>{const a=R(2,6);return mkg(\'因式分解 x²+\'+(2*a)+\'x+\'+(a*a)+\' =\',\'(x+\'+a+\')²\',[\'(x−\'+a+\')²\',\'(x+\'+a+\')(x−\'+a+\')\',\'x(x+\'+2*a+\')\'])}","sampleStem":"因式分解 x²+10x+25 ="}', 3, '["初二","第14章 整式的乘法与因式分解","动态随机"]', 'PROTOTYPE', 1, 2, 1);
INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (165, 'g8', 14, 55, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '因式分解 4x+4y =', '["16(x+y)","4x(x+y)","4(x+y)","x(4+y)"]', '{"index":2}', '动态随机题型（每次闯关随机生成参数与选项）', 'c14_g2_2', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>{const a=R(2,6),b=R(2,6);return mkg(\'因式分解 \'+a+\'x+\'+a+\'y =\',a+\'(x+y)\',[a+\'x(x+y)\',(a*a)+\'(x+y)\',\'x(\'+a+\'+y)\']);}","sampleStem":"因式分解 4x+4y ="}', 3, '["初二","第14章 整式的乘法与因式分解","动态随机"]', 'PROTOTYPE', 1, 3, 1);
