INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (169, 'g8', 15, 57, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '约分：(6b x²)/(2x) =', '["12x","6x²","6","6x"]', '{"index":3}', '动态随机题型（每次闯关随机生成参数与选项）', 'c15_g0_0', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>{const a=R(2,9),b=R(2,6);return mkg(\'约分：(\'+a+\'b x²)/(\'+b+\'x) =\',a+\'x\',[a+\'x²\',(a*b)+\'x\',a+\'\'])}","sampleStem":"约分：(6b x²)/(2x) ="}', 1, '["初二","第15章 分式","动态随机"]', 'PROTOTYPE', 1, 1, 1);
