INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (171, 'g8', 15, 57, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '计算 9/x + 7/x =', '["16x","2/x","63/x","16/x"]', '{"index":3}', '动态随机题型（每次闯关随机生成参数与选项）', 'c15_g0_2', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>{const a=R(2,9),b=R(2,9);return mkg(\'计算 \'+a+\'/x + \'+b+\'/x =\',(a+b)+\'/x\',[(a*b)+\'/x\',(a+b)+\'x\',(a-b)+\'/x\']);}","sampleStem":"计算 9/x + 7/x ="}', 1, '["初二","第15章 分式","动态随机"]', 'PROTOTYPE', 1, 3, 1);
INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (172, 'g8', 15, 58, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '分式 (x−3)/x 的值为 0，则 x =', '["任意值","3","0","-3"]', '{"index":1}', '动态随机题型（每次闯关随机生成参数与选项）', 'c15_g1_0', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>{const d=R(2,9);return mkg(\'分式 (x−\'+d+\')/x 的值为 0，则 x =\',String(d),[\'0\',String(-d),\'任意值\'])}","sampleStem":"分式 (x−3)/x 的值为 0，则 x ="}', 2, '["初二","第15章 分式","动态随机"]', 'PROTOTYPE', 1, 1, 1);
