INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (205, 'g8', 18, 69, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '▱ABCD 中 ∠A=76°，则 ∠B =', '["166°","52°","76°","104°"]', '{"index":3}', '动态随机题型（每次闯关随机生成参数与选项）', 'c18_g0_0', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>{const a=R(50,80);return mkg(\'▱ABCD 中 ∠A=\'+a+\'°，则 ∠B =\',(180-a)+\'°\',[a+\'°\',(90+a)+\'°\',(180-a)/2+\'°\'])}","sampleStem":"▱ABCD 中 ∠A=76°，则 ∠B ="}', 1, '["初二","第18章 平行四边形","动态随机"]', 'PROTOTYPE', 1, 1, 1);
INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (206, 'g8', 18, 69, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '平行四边形的对角线', '["互相垂直平分","互相平分","互相垂直","相等"]', '{"index":1}', '动态随机题型（每次闯关随机生成参数与选项）', 'c18_g0_1', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>mkg(\'平行四边形的对角线\',o=\'互相平分\',[\'互相垂直\',\'相等\',\'互相垂直平分\',\'相交于一点但不平分\'])","sampleStem":"平行四边形的对角线"}', 1, '["初二","第18章 平行四边形","动态随机"]', 'PROTOTYPE', 1, 2, 1);
