INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (208, 'g8', 18, 70, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '△ABC 中，D、E 分别为 AB、AC 中点，BC=16，则 DE =', '["1","16","8","64"]', '{"index":2}', '动态随机题型（每次闯关随机生成参数与选项）', 'c18_g1_0', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>{const m=R(2,9);return mkg(\'△ABC 中，D、E 分别为 AB、AC 中点，BC=\'+String(2*m)+\'，则 DE =\',String(m),[String(2*m),String(m*m),\'1\'])}","sampleStem":"△ABC 中，D、E 分别为 AB、AC 中点，BC=16，则 DE ="}', 2, '["初二","第18章 平行四边形","动态随机"]', 'PROTOTYPE', 1, 1, 1);
