INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (229, 'g8', 20, 77, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '数据 8,7,2,1,2 的平均数是', '["3","4","5","20"]', '{"index":1}', '动态随机题型（每次闯关随机生成参数与选项）', 'c20_g0_0', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>{const a=[R(1,9),R(1,9),R(1,9),R(1,9),R(1,9)];const s=a.reduce((x,y)=>x+y,0);if(s%5!==0){a[0]+=5-(s%5);}const sum=a.reduce((x,y)=>x+y,0);return mkg(\'数据 \'+a.join(\',\')+\' 的平均数是\',String(sum/5),[String(sum/5+1),String(sum/5-1),String(sum)])}","sampleStem":"数据 8,7,2,1,2 的平均数是"}', 1, '["初二","第20章 数据的分析","动态随机"]', 'PROTOTYPE', 1, 1, 1);
INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (230, 'g8', 20, 77, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '数据 6,7,8,9,10 的中位数是', '["6","9","7","8"]', '{"index":3}', '动态随机题型（每次闯关随机生成参数与选项）', 'c20_g0_1', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>{const m=R(1,9);const a=[m-2,m-1,m,m+1,m+2];return mkg(\'数据 \'+a.join(\',\')+\' 的中位数是\',String(m),[String(m+1),String(m-1),\'6\'])}","sampleStem":"数据 6,7,8,9,10 的中位数是"}', 1, '["初二","第20章 数据的分析","动态随机"]', 'PROTOTYPE', 1, 2, 1);
INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (231, 'g8', 20, 77, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '数据 4,4,4,5,6 的众数是', '["没有众数","5","4","6"]', '{"index":2}', '动态随机题型（每次闯关随机生成参数与选项）', 'c20_g0_2', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>{const m=R(1,5);return mkg(\'数据 \'+[m,m,m,m+1,m+2].join(\',\')+\' 的众数是\',String(m),[String(m+1),String(m+2),\'没有众数\']);}","sampleStem":"数据 4,4,4,5,6 的众数是"}', 1, '["初二","第20章 数据的分析","动态随机"]', 'PROTOTYPE', 1, 3, 1);
INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (232, 'g8', 20, 78, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '数据 -1,1,3,5,7 的方差与原数据 1,3,5,7,9 的方差关系是', '["变大 2","变为原来的 1/2","变小 2","相同"]', '{"index":3}', '动态随机题型（每次闯关随机生成参数与选项）', 'c20_g1_0', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>{const d=R(1,3);return mkg(\'数据 \'+(1-d)+\',\'+(3-d)+\',\'+(5-d)+\',\'+(7-d)+\',\'+(9-d)+\' 的方差与原数据 1,3,5,7,9 的方差关系是\',\'相同\',[\'变大 2\',\'变小 2\',\'变为原来的 1/2\'])}","sampleStem":"数据 -1,1,3,5,7 的方差与原数据 1,3,5,7,9 的方差关系是"}', 2, '["初二","第20章 数据的分析","动态随机"]', 'PROTOTYPE', 1, 1, 1);
INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (233, 'g8', 20, 78, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '数据 0,2,4,6,8 的方差是', '["4","9","2","8"]', '{"index":3}', '动态随机题型（每次闯关随机生成参数与选项）', 'c20_g1_1', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>{const d=R(1,2);return mkg(\'数据 \'+[1-d,3-d,5-d,7-d,9-d].join(\',\')+\' 的方差是\',String(8*d*d),[String(8*d),String(4*d*d),String(2*d)])}","sampleStem":"数据 0,2,4,6,8 的方差是"}', 2, '["初二","第20章 数据的分析","动态随机"]', 'PROTOTYPE', 1, 2, 1);
INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (234, 'g8', 20, 78, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '甲 2 次测试共得 16 分，乙 4 次共得 32 分，总成绩更高的是', '["无法确定","乙","一样高","乙和甲都一样"]', '{"index":1}', '动态随机题型（每次闯关随机生成参数与选项）', 'c20_g1_2', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>{const w1=R(2,4),w2=R(2,4),m1=R(5,9),m2=R(5,9);const ans=(w1*m1>w2*m2)?\'甲\':\'乙\';return mkg(\'甲 \'+w1+\' 次测试共得 \'+(w1*m1)+\' 分，乙 \'+w2+\' 次共得 \'+(w2*m2)+\' 分，总成绩更高的是\',ans,[\'一样高\',\'无法确定\',\'乙和甲都一样\']);}","sampleStem":"甲 2 次测试共得 16 分，乙 4 次共得 32 分，总成绩更高的是"}', 2, '["初二","第20章 数据的分析","动态随机"]', 'PROTOTYPE', 1, 3, 1);
