INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (303, 'g9', 26, 101, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '反比例函数 y=k/x（k≠0）的图象是', '["双曲线","圆","直线","抛物线"]', '{"index":0}', '动态随机题型（每次闯关随机生成参数与选项）', 'c26_g0_2', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>{return mkg(\'反比例函数 y=k/x（k≠0）的图象是\',\'双曲线\',[\'抛物线\',\'直线\',\'圆\']);}","sampleStem":"反比例函数 y=k/x（k≠0）的图象是"}', 1, '["初三","第26章 反比例函数","动态随机"]', 'PROTOTYPE', 1, 3, 1);
INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (304, 'g9', 26, 102, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '反比例函数 y=1/x 图象上一点到 x 轴、y 轴的垂线与坐标轴围成的矩形面积是', '["0","1","2","3"]', '{"index":1}', '动态随机题型（每次闯关随机生成参数与选项）', 'c26_g1_0', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>{const k=R(1,6);return mkg(\'反比例函数 y=\'+k+\'/x 图象上一点到 x 轴、y 轴的垂线与坐标轴围成的矩形面积是\',String(k),[String(2*k),String(k*k),\'1\'])}","sampleStem":"反比例函数 y=1/x 图象上一点到 x 轴、y 轴的垂线与坐标轴围成的矩形面积是"}', 2, '["初三","第26章 反比例函数","动态随机"]', 'PROTOTYPE', 1, 1, 1);
