INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (351, 'h1', 30, 117, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '若集合 A={x | x>6}，则下列哪个元素属于 A', '["0","8","6","5"]', '{"index":1}', '动态随机题型（每次闯关随机生成参数与选项）', 'c30_g0_2', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>{const k=R(2,6);return mkg(\'若集合 A={x | x>\'+k+\'}，则下列哪个元素属于 A\',String(k+2),[String(k),String(k-1),\'0\']);}","sampleStem":"若集合 A={x | x>6}，则下列哪个元素属于 A"}', 1, '["高一","第1章 集合与常用逻辑用语","动态随机"]', 'PROTOTYPE', 1, 3, 1);
INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (352, 'h1', 30, 118, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', 'A={2,4}，B={4}，则 B 与 A 的关系是', '["B ⊆ A","B ∩ A = ∅","B ∈ A","B ⊇ A"]', '{"index":0}', '动态随机题型（每次闯关随机生成参数与选项）', 'c30_g1_0', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>{const a=R(1,3),b=R(4,7);return mkg(\'A={\'+a+\',\'+b+\'}，B={\'+b+\'}，则 B 与 A 的关系是\',\'B ⊆ A\',[\'B ⊇ A\',\'B ∈ A\',\'B ∩ A = ∅\'])}","sampleStem":"A={2,4}，B={4}，则 B 与 A 的关系是"}', 2, '["高一","第1章 集合与常用逻辑用语","动态随机"]', 'PROTOTYPE', 1, 1, 1);
INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (353, 'h1', 30, 118, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '"x>2" 是 "x²>4" 的什么条件', '["充要条件","必要不充分条件","充分不必要条件","既不充分也不必要条件"]', '{"index":2}', '动态随机题型（每次闯关随机生成参数与选项）', 'c30_g1_1', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>mkg(\'\\"x>2\\" 是 \\"x²>4\\" 的什么条件\',\'充分不必要条件\',[\'必要不充分条件\',\'充要条件\',\'既不充分也不必要条件\'])","sampleStem":"\\"x>2\\" 是 \\"x²>4\\" 的什么条件"}', 2, '["高一","第1章 集合与常用逻辑用语","动态随机"]', 'PROTOTYPE', 1, 2, 1);
