INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (355, 'h1', 30, 119, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '方程 x² = 9 的解集用列举法表示是', '["{3}","{3,−3}","{9}","{−3}"]', '{"index":1}', '动态随机题型（每次闯关随机生成参数与选项）', 'c30_g2_0', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>{const a=R(2,5);return mkg(\'方程 x² = \'+a*a+\' 的解集用列举法表示是\',\'{\'+a+\',−\'+a+\'}\',[\'{\'+a+\'}\',\'{\'+a*a+\'}\',\'{−\'+a+\'}\'])}","sampleStem":"方程 x² = 9 的解集用列举法表示是"}', 3, '["高一","第1章 集合与常用逻辑用语","动态随机"]', 'PROTOTYPE', 1, 1, 1);
INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (356, 'h1', 30, 119, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '已知 A={1,2,3}，B={2,3,4}，则 A∩B 的子集个数是', '["4","8","2","3"]', '{"index":0}', '动态随机题型（每次闯关随机生成参数与选项）', 'c30_g2_1', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>mkg(\'已知 A={1,2,3}，B={2,3,4}，则 A∩B 的子集个数是\',\'4\',[\'2\',\'3\',\'8\'])","sampleStem":"已知 A={1,2,3}，B={2,3,4}，则 A∩B 的子集个数是"}', 3, '["高一","第1章 集合与常用逻辑用语","动态随机"]', 'PROTOTYPE', 1, 2, 1);
INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (357, 'h1', 30, 119, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '"∀x∈R，x²≥0" 的否定是', '["∃x∈R，x²<0","∃x∈R，x²≥0","∀x∈R，x²>0","∀x∈R，x²≤0"]', '{"index":0}', '动态随机题型（每次闯关随机生成参数与选项）', 'c30_g2_2', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>{return mkg(\'\\"∀x∈R，x²≥0\\" 的否定是\',\'∃x∈R，x²<0\',[\'∀x∈R，x²≤0\',\'∃x∈R，x²≥0\',\'∀x∈R，x²>0\']);}","sampleStem":"\\"∀x∈R，x²≥0\\" 的否定是"}', 3, '["高一","第1章 集合与常用逻辑用语","动态随机"]', 'PROTOTYPE', 1, 3, 1);
INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (358, 'h1', 30, 120, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '集合 A={x | x²−6x+9 = 0} = A{x=3 的单元素集}，若 A 只有一个元素，方程 x²−6x+m=0 中 m 等于', '["9","6","-9","3"]', '{"index":0}', '动态随机题型（每次闯关随机生成参数与选项）', 'c30_g3_0', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>{const k=R(2,4);return mkg(\'集合 A={x | x²−\'+(2*k)+\'x+\'+(k*k)+\' = 0} = A{x=\'+k+\' 的单元素集}，若 A 只有一个元素，方程 x²−\'+(2*k)+\'x+m=0 中 m 等于\',String(k*k),[String(k),String(2*k),String(-k*k)])}","sampleStem":"集合 A={x | x²−6x+9 = 0} = A{x=3 的单元素集}，若 A 只有一个元素，方程 x²−6x+m=0 中 m 等于"}', 4, '["高一","第1章 集合与常用逻辑用语","动态随机"]', 'PROTOTYPE', 1, 1, 1);
INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (359, 'h1', 30, 120, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '已知集合 A={x | x²−3x+2=0}，B={x | ax−2=0}，若 B⊆A，则 a 的取值集合是', '["{1,2}","{0,1,2}","{0,2}","{1}"]', '{"index":1}', '动态随机题型（每次闯关随机生成参数与选项）', 'c30_g3_1', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>mkg(\'已知集合 A={x | x²−3x+2=0}，B={x | ax−2=0}，若 B⊆A，则 a 的取值集合是\',\'{0,1,2}\',[\'{1,2}\',\'{1}\',\'{0,2}\'])","sampleStem":"已知集合 A={x | x²−3x+2=0}，B={x | ax−2=0}，若 B⊆A，则 a 的取值集合是"}', 4, '["高一","第1章 集合与常用逻辑用语","动态随机"]', 'PROTOTYPE', 1, 2, 1);
INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (360, 'h1', 30, 120, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', 'p：x>1，q：x²>1，则 p 是 q 的什么条件', '["既不充分也不必要","充要条件","必要不充分条件","充分不必要条件"]', '{"index":3}', '动态随机题型（每次闯关随机生成参数与选项）', 'c30_g3_2', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>{return mkg(\'p：x>1，q：x²>1，则 p 是 q 的什么条件\',\'充分不必要条件\',[\'必要不充分条件\',\'充要条件\',\'既不充分也不必要\']);}","sampleStem":"p：x>1，q：x²>1，则 p 是 q 的什么条件"}', 4, '["高一","第1章 集合与常用逻辑用语","动态随机"]', 'PROTOTYPE', 1, 3, 1);
INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (361, 'h1', 31, 121, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '不等式 x² > 4（x>0）的解集是', '["x < 2","x > 2","x > −2","x > 4"]', '{"index":1}', '动态随机题型（每次闯关随机生成参数与选项）', 'c31_g0_0', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>{const a=R(1,5);return mkg(\'不等式 x² > \'+a*a+\'（x>0）的解集是\',\'x > \'+a,[\'x < \'+a,\'x > −\'+a,\'x > \'+(a*a)])}","sampleStem":"不等式 x² > 4（x>0）的解集是"}', 1, '["高一","第2章 一元二次函数、方程和不等式","动态随机"]', 'PROTOTYPE', 1, 1, 1);
INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (362, 'h1', 31, 121, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', 'a+b ≥ 2√(ab)（a,b>0）当且仅当什么时取等号', '["a = −b","ab = 1","a = 2b","a = b"]', '{"index":3}', '动态随机题型（每次闯关随机生成参数与选项）', 'c31_g0_1', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>mkg(\'a+b ≥ 2√(ab)（a,b>0）当且仅当什么时取等号\',\'a = b\',[\'a = −b\',\'ab = 1\',\'a = 2b\'])","sampleStem":"a+b ≥ 2√(ab)（a,b>0）当且仅当什么时取等号"}', 1, '["高一","第2章 一元二次函数、方程和不等式","动态随机"]', 'PROTOTYPE', 1, 2, 1);
INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (363, 'h1', 31, 121, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '解不等式 x−3 > 0', '["x > 3","x < 3","x > 4","x < 4"]', '{"index":0}', '动态随机题型（每次闯关随机生成参数与选项）', 'c31_g0_2', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>{const k=R(2,5);return mkg(\'解不等式 x−\'+k+\' > 0\',\'x > \'+k,[\'x < \'+k,\'x > \'+(k+1),\'x < \'+(k+1)]);}","sampleStem":"解不等式 x−3 > 0"}', 1, '["高一","第2章 一元二次函数、方程和不等式","动态随机"]', 'PROTOTYPE', 1, 3, 1);
INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (364, 'h1', 31, 122, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '不妨设 a+b=10（a,b>0），则 ab 的最大值是', '["25","24","20","50"]', '{"index":0}', '动态随机题型（每次闯关随机生成参数与选项）', 'c31_g1_0', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>{let a=R(1,4),b=R(1,4);if(a===b){b=5;}return mkg(\'不妨设 a+b=10（a,b>0），则 ab 的最大值是\',\'25\',[\'24\',\'20\',\'50\'])}","sampleStem":"不妨设 a+b=10（a,b>0），则 ab 的最大值是"}', 2, '["高一","第2章 一元二次函数、方程和不等式","动态随机"]', 'PROTOTYPE', 1, 1, 1);
INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (365, 'h1', 31, 122, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '方程 x²−10x+25=0 的根的情况', '["无实根","两个不等实根","一个正根一个负根","有两个相等的实根"]', '{"index":3}', '动态随机题型（每次闯关随机生成参数与选项）', 'c31_g1_1', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>{const k=R(2,5);return mkg(\'方程 x²−\'+(k*2)+\'x+\'+(k*k)+\'=0 的根的情况\',\'有两个相等的实根\',[\'两个不等实根\',\'无实根\',\'一个正根一个负根\'])}","sampleStem":"方程 x²−10x+25=0 的根的情况"}', 2, '["高一","第2章 一元二次函数、方程和不等式","动态随机"]', 'PROTOTYPE', 1, 2, 1);
INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (366, 'h1', 31, 122, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '已知 x>0，则 x + 4/x 的最小值是', '["16","8","2","4"]', '{"index":3}', '动态随机题型（每次闯关随机生成参数与选项）', 'c31_g1_2', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>{return mkg(\'已知 x>0，则 x + 4/x 的最小值是\',\'4\',[\'2\',\'8\',\'16\']);}","sampleStem":"已知 x>0，则 x + 4/x 的最小值是"}', 2, '["高一","第2章 一元二次函数、方程和不等式","动态随机"]', 'PROTOTYPE', 1, 3, 1);
