INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (375, 'h1', 32, 125, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', 'f(x)=5x−1 是增函数的条件', '["a > 0","a ≥ 1","a < 0","a = 0"]', '{"index":0}', '动态随机题型（每次闯关随机生成参数与选项）', 'c32_g0_2', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>{const a=R(1,5);return mkg(\'f(x)=\'+a+\'x−1 是增函数的条件\',\'a > 0\',[\'a < 0\',\'a = 0\',\'a ≥ 1\']);}","sampleStem":"f(x)=5x−1 是增函数的条件"}', 1, '["高一","第3章 函数的概念与性质","动态随机"]', 'PROTOTYPE', 1, 3, 1);
INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (376, 'h1', 32, 126, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '函数 f(x)=√(x−1) 的定义域是', '["x ≤ 1","x ≥ 1","x > 1","全体实数"]', '{"index":1}', '动态随机题型（每次闯关随机生成参数与选项）', 'c32_g1_0', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>mkg(\'函数 f(x)=√(x−1) 的定义域是\',\'x ≥ 1\',[\'x > 1\',\'x ≤ 1\',\'全体实数\'])","sampleStem":"函数 f(x)=√(x−1) 的定义域是"}', 2, '["高一","第3章 函数的概念与性质","动态随机"]', 'PROTOTYPE', 1, 1, 1);
INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (377, 'h1', 32, 126, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', 'f(x)=x²+4x+6 的单调递增区间是', '["x ≥ 2","x ≤ −2","x ≥ 4","x ≥ −2"]', '{"index":3}', '动态随机题型（每次闯关随机生成参数与选项）', 'c32_g1_1', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>{const a=R(1,4),b=R(1,4);return mkg(\'f(x)=x²+\'+(2*a)+\'x+\'+(a*a+b)+\' 的单调递增区间是\',\'x ≥ −\'+a,[\'x ≥ \'+a,\'x ≤ −\'+a,\'x ≥ \'+(a*a)])}","sampleStem":"f(x)=x²+4x+6 的单调递增区间是"}', 2, '["高一","第3章 函数的概念与性质","动态随机"]', 'PROTOTYPE', 1, 2, 1);
INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (378, 'h1', 32, 126, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '若 f(x) 是奇函数且 f(2)=3，则 f(−2) =', '["−3","0","3","−6"]', '{"index":0}', '动态随机题型（每次闯关随机生成参数与选项）', 'c32_g1_2', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>{return mkg(\'若 f(x) 是奇函数且 f(2)=3，则 f(−2) =\',\'−3\',[\'3\',\'0\',\'−6\']);}","sampleStem":"若 f(x) 是奇函数且 f(2)=3，则 f(−2) ="}', 2, '["高一","第3章 函数的概念与性质","动态随机"]', 'PROTOTYPE', 1, 3, 1);
INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (379, 'h1', 32, 127, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '下列函数中既是奇函数又是增函数的是', '["y = 1/x","y = −x","y = x³","y = x²"]', '{"index":2}', '动态随机题型（每次闯关随机生成参数与选项）', 'c32_g2_0', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>mkg(\'下列函数中既是奇函数又是增函数的是\',\'y = x³\',[\'y = x²\',\'y = 1/x\',\'y = −x\'])","sampleStem":"下列函数中既是奇函数又是增函数的是"}', 3, '["高一","第3章 函数的概念与性质","动态随机"]', 'PROTOTYPE', 1, 1, 1);
INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (380, 'h1', 32, 127, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '函数 y = x + 1/x（x>0）的减区间是', '["[1,+∞)","(0,+∞)","(0,1]","[2,+∞)"]', '{"index":2}', '动态随机题型（每次闯关随机生成参数与选项）', 'c32_g2_1', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>mkg(\'函数 y = x + 1/x（x>0）的减区间是\',\'(0,1]\',[\'[1,+∞)\',\'(0,+∞)\',\'[2,+∞)\'])","sampleStem":"函数 y = x + 1/x（x>0）的减区间是"}', 3, '["高一","第3章 函数的概念与性质","动态随机"]', 'PROTOTYPE', 1, 2, 1);
INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (381, 'h1', 32, 127, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', 'f(x) 在 [a,+∞) 增、在 (−∞,a] 减，且最大值 5，则 f(x) 的图象最高点横坐标是', '["1","5","0","-1"]', '{"index":0}', '动态随机题型（每次闯关随机生成参数与选项）', 'c32_g2_2', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>{const a=R(1,3);return mkg(\'f(x) 在 [a,+∞) 增、在 (−∞,a] 减，且最大值 5，则 f(x) 的图象最高点横坐标是\',String(a),[String(-a),\'0\',\'5\']);}","sampleStem":"f(x) 在 [a,+∞) 增、在 (−∞,a] 减，且最大值 5，则 f(x) 的图象最高点横坐标是"}', 3, '["高一","第3章 函数的概念与性质","动态随机"]', 'PROTOTYPE', 1, 3, 1);
INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (382, 'h1', 32, 128, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '已知 f(x+1) = x²，则 f(3) =', '["4","9","3","6"]', '{"index":0}', '动态随机题型（每次闯关随机生成参数与选项）', 'c32_g3_0', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>mkg(\'已知 f(x+1) = x²，则 f(3) =\',\'4\',[\'9\',\'3\',\'6\'])","sampleStem":"已知 f(x+1) = x²，则 f(3) ="}', 4, '["高一","第3章 函数的概念与性质","动态随机"]', 'PROTOTYPE', 1, 1, 1);
INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (383, 'h1', 32, 128, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '偶函数 f(x) 在 [0,+∞) 上递减，比较 f(−2) 与 f(1)', '["f(−2) < f(1)","f(−2) > f(1)","f(−2) = f(1)","无法比较"]', '{"index":0}', '动态随机题型（每次闯关随机生成参数与选项）', 'c32_g3_1', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>mkg(\'偶函数 f(x) 在 [0,+∞) 上递减，比较 f(−2) 与 f(1)\',\'f(−2) < f(1)\',[\'f(−2) > f(1)\',\'f(−2) = f(1)\',\'无法比较\'])","sampleStem":"偶函数 f(x) 在 [0,+∞) 上递减，比较 f(−2) 与 f(1)"}', 4, '["高一","第3章 函数的概念与性质","动态随机"]', 'PROTOTYPE', 1, 2, 1);
INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (384, 'h1', 32, 128, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '若 f(x) 是定义在 R 上的奇函数，x>0 时 f(x)=x+3，则 f(0) =', '["3","0","1","−1"]', '{"index":1}', '动态随机题型（每次闯关随机生成参数与选项）', 'c32_g3_2', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>{const k=R(2,4);return mkg(\'若 f(x) 是定义在 R 上的奇函数，x>0 时 f(x)=x+\'+k+\'，则 f(0) =\',\'0\',[\'1\',\'−1\',String(k)]);}","sampleStem":"若 f(x) 是定义在 R 上的奇函数，x>0 时 f(x)=x+3，则 f(0) ="}', 4, '["高一","第3章 函数的概念与性质","动态随机"]', 'PROTOTYPE', 1, 3, 1);
INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (385, 'h1', 33, 129, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '计算 2^3 =', '["8","5","6","9"]', '{"index":0}', '动态随机题型（每次闯关随机生成参数与选项）', 'c33_g0_0', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>{const a=R(2,4),n=R(2,3);return mkg(\'计算 \'+a+\'^\'+n+\' =\',String(Math.pow(a,n)),[String(a*n),String(a+n),String(Math.pow(a,n)+1)])}","sampleStem":"计算 2^3 ="}', 1, '["高一","第4章 指数函数与对数函数","动态随机"]', 'PROTOTYPE', 1, 1, 1);
