INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (412, 'h1', 35, 138, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', 'a=(1,3)，b=(3,1)，则 a·b =', '["0","6","8","10"]', '{"index":1}', '动态随机题型（每次闯关随机生成参数与选项）', 'c35_g1_0', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>{const a1=R(1,3),a2=R(1,3),b1=R(1,3),b2=R(1,3);return mkg(\'a=(\'+a1+\',\'+a2+\')，b=(\'+b1+\',\'+b2+\')，则 a·b =\',String(a1*b1+a2*b2),[String(a1*b2+a2*b1),String(a1+a2+b1+b2),String(a1*b1-a2*b2)])}","sampleStem":"a=(1,3)，b=(3,1)，则 a·b ="}', 2, '["高一","第6章 平面向量","动态随机"]', 'PROTOTYPE', 1, 1, 1);
