INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (422, 'h1', 36, 141, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '(1+i)+(1−i) =', '["(1+2i)","(0)","(2)","(2−2i)"]', '{"index":2}', '动态随机题型（每次闯关随机生成参数与选项）', 'c36_g0_1', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>{const a=R(1,4),b=R(1,4);return mkg(\'(1+i)+(\'+a+\'−i) =\',\'(\'+(a+1)+\')\',[\'(\'+(a-1)+\')\',\'(\'+a+\'+2i)\',\'(\'+(a+1)+\'−2i)\'])}","sampleStem":"(1+i)+(1−i) ="}', 1, '["高一","第7章 复数","动态随机"]', 'PROTOTYPE', 1, 2, 1);
