INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (466, 'h1', 39, 156, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '袋中 3 红 2 白，不放回取两次都是红的概率', '["9/25","3/10","1/2","3/5"]', '{"index":1}', '动态随机题型（每次闯关随机生成参数与选项）', 'c39_g3_0', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>mkg(\'袋中 3 红 2 白，不放回取两次都是红的概率\',\'3/10\',[\'3/5\',\'1/2\',\'9/25\'])","sampleStem":"袋中 3 红 2 白，不放回取两次都是红的概率"}', 4, '["高一","第10章 概率","动态随机"]', 'PROTOTYPE', 1, 1, 1);
INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (467, 'h1', 39, 156, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '条件概率公式 P(B|A) =', '["P(AB)/P(A)","P(A∪B)/P(A)","P(A)P(B)","P(A)/P(B)"]', '{"index":0}', '动态随机题型（每次闯关随机生成参数与选项）', 'c39_g3_1', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>mkg(\'条件概率公式 P(B|A) =\',\'P(AB)/P(A)\',[\'P(A)/P(B)\',\'P(A)P(B)\',\'P(A∪B)/P(A)\'])","sampleStem":"条件概率公式 P(B|A) ="}', 4, '["高一","第10章 概率","动态随机"]', 'PROTOTYPE', 1, 2, 1);
