INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (469, 'h2', 40, 157, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', 'a=(1,0,0)，b=(0,1,0)，则 a·b =', '["2","0","−1","1"]', '{"index":1}', '动态随机题型（每次闯关随机生成参数与选项）', 'c40_g0_0', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>{const a=R(1,3),b=R(1,3),c=R(1,3);return mkg(\'a=(1,0,0)，b=(0,1,0)，则 a·b =\',\'0\',[\'1\',\'−1\',\'2\'])}","sampleStem":"a=(1,0,0)，b=(0,1,0)，则 a·b ="}', 1, '["高二","第1章 空间向量与立体几何","动态随机"]', 'PROTOTYPE', 1, 1, 1);
