INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (485, 'h2', 41, 162, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '两条垂直直线的斜率之积（均存在且不为 0）是', '["−1","1","0","−2"]', '{"index":0}', '动态随机题型（每次闯关随机生成参数与选项）', 'c41_g1_1', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>mkg(\'两条垂直直线的斜率之积（均存在且不为 0）是\',\'−1\',[\'1\',\'0\',\'−2\'])","sampleStem":"两条垂直直线的斜率之积（均存在且不为 0）是"}', 2, '["高二","第2章 直线和圆的方程","动态随机"]', 'PROTOTYPE', 1, 2, 1);
INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (486, 'h2', 41, 162, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '点 (1,2) 到直线 y=x 的距离是 |1−2|/√2，当 1=3 时为', '["√2/2","1/2","√2","1"]', '{"index":0}', '动态随机题型（每次闯关随机生成参数与选项）', 'c41_g1_2', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>{const k=R(1,3);return mkg(\'点 (\'+k+\',2) 到直线 y=x 的距离是 |\'+k+\'−2|/√2，当 \'+k+\'=3 时为\',\'√2/2\',[\'√2\',\'1\',\'1/2\']);}","sampleStem":"点 (1,2) 到直线 y=x 的距离是 |1−2|/√2，当 1=3 时为"}', 2, '["高二","第2章 直线和圆的方程","动态随机"]', 'PROTOTYPE', 1, 3, 1);
INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (487, 'h2', 41, 163, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '圆心到直线距离 1、半径 2，直线与圆交点个数是', '["2","1","不确定","0"]', '{"index":0}', '动态随机题型（每次闯关随机生成参数与选项）', 'c41_g2_0', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>{const d=R(1,3);return mkg(\'圆心到直线距离 \'+d+\'、半径 2，直线与圆交点个数是\',d<2?\'2\':\'1\',d<2?[\'1\',\'0\',\'不确定\']:[\'2\',\'0\',\'不确定\'])}","sampleStem":"圆心到直线距离 1、半径 2，直线与圆交点个数是"}', 3, '["高二","第2章 直线和圆的方程","动态随机"]', 'PROTOTYPE', 1, 1, 1);
INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (488, 'h2', 41, 163, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '圆 (x−1)²+y²=1 与直线 x=3 的位置关系', '["相交","重合","相离","相切"]', '{"index":2}', '动态随机题型（每次闯关随机生成参数与选项）', 'c41_g2_1', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>mkg(\'圆 (x−1)²+y²=1 与直线 x=3 的位置关系\',\'相离\',[\'相切\',\'相交\',\'重合\'])","sampleStem":"圆 (x−1)²+y²=1 与直线 x=3 的位置关系"}', 3, '["高二","第2章 直线和圆的方程","动态随机"]', 'PROTOTYPE', 1, 2, 1);
INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (489, 'h2', 41, 163, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '两平行直线 x+y−1=0 与 x+y=0 间距离是', '["1/2","1√2","1","1/2√2/2"]', '{"index":3}', '动态随机题型（每次闯关随机生成参数与选项）', 'c41_g2_2', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>{const a=R(1,4);return mkg(\'两平行直线 x+y−\'+a+\'=0 与 x+y=0 间距离是\',frac(a,2)+\'√2/2\',[\'\'+a+\'√2\',frac(a,2),\'\'+a]);}","sampleStem":"两平行直线 x+y−1=0 与 x+y=0 间距离是"}', 3, '["高二","第2章 直线和圆的方程","动态随机"]', 'PROTOTYPE', 1, 3, 1);
INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (490, 'h2', 41, 164, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '过圆 x²+y²=4 上一点作圆的切线，切线与半径所在直线', '["平行","斜交成 45°","重合","垂直"]', '{"index":3}', '动态随机题型（每次闯关随机生成参数与选项）', 'c41_g3_0', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>mkg(\'过圆 x²+y²=4 上一点作圆的切线，切线与半径所在直线\',\'垂直\',[\'平行\',\'斜交成 45°\',\'重合\'])","sampleStem":"过圆 x²+y²=4 上一点作圆的切线，切线与半径所在直线"}', 4, '["高二","第2章 直线和圆的方程","动态随机"]', 'PROTOTYPE', 1, 1, 1);
INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (491, 'h2', 41, 164, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '直线 3x+6y=0 的斜率是', '["1/-2","1/-2+1","1","1/2"]', '{"index":0}', '动态随机题型（每次闯关随机生成参数与选项）', 'c41_g3_1', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>{const a=R(1,3),b=R(4,6);return mkg(\'直线 \'+a+\'x+\'+b+\'y=0 的斜率是\',frac(-a,b),[frac(a,b),frac(b,a),frac(-b,a)])}","sampleStem":"直线 3x+6y=0 的斜率是"}', 4, '["高二","第2章 直线和圆的方程","动态随机"]', 'PROTOTYPE', 1, 2, 1);
INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (492, 'h2', 41, 164, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '圆 C₁: x²+y²=1 与 C₂: (x−3)²+y²=1 的位置关系', '["外切","外离","相交","内含"]', '{"index":1}', '动态随机题型（每次闯关随机生成参数与选项）', 'c41_g3_2', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>{return mkg(\'圆 C₁: x²+y²=1 与 C₂: (x−3)²+y²=1 的位置关系\',\'外离\',[\'外切\',\'相交\',\'内含\']);}","sampleStem":"圆 C₁: x²+y²=1 与 C₂: (x−3)²+y²=1 的位置关系"}', 4, '["高二","第2章 直线和圆的方程","动态随机"]', 'PROTOTYPE', 1, 3, 1);
INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (493, 'h2', 42, 165, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '椭圆 x²/4+y²/3=1 的长轴长是', '["√4","8","4","2"]', '{"index":2}', '动态随机题型（每次闯关随机生成参数与选项）', 'c42_g0_0', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>mkg(\'椭圆 x²/4+y²/3=1 的长轴长是\',\'4\',[\'2\',\'√4\',\'8\'])","sampleStem":"椭圆 x²/4+y²/3=1 的长轴长是"}', 1, '["高二","第3章 圆锥曲线的方程","动态随机"]', 'PROTOTYPE', 1, 1, 1);
