INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (496, 'h2', 42, 166, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '椭圆 x²/16+y²/15=1 的离心率 e = c/a = 1/4，则 c =', '["16","2","4","1"]', '{"index":3}', '动态随机题型（每次闯关随机生成参数与选项）', 'c42_g1_0', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>{const a=R(2,4);return mkg(\'椭圆 x²/\'+(a*a)+\'+y²/\'+(a*a-1)+\'=1 的离心率 e = c/a = 1/\'+a+\'，则 c =\',\'1\',[\'2\',String(a),String(a*a)])}","sampleStem":"椭圆 x²/16+y²/15=1 的离心率 e = c/a = 1/4，则 c ="}', 2, '["高二","第3章 圆锥曲线的方程","动态随机"]', 'PROTOTYPE', 1, 1, 1);
