INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (506, 'h2', 43, 169, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '等比数列 2,4,8 的公比是', '["2","1","4","3"]', '{"index":0}', '动态随机题型（每次闯关随机生成参数与选项）', 'c43_g0_1', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>{const q=R(2,3);return mkg(\'等比数列 2,4,8 的公比是\',String(q),[String(q+1),String(q-1),\'1\'])}","sampleStem":"等比数列 2,4,8 的公比是"}', 1, '["高二","第4章 数列","动态随机"]', 'PROTOTYPE', 1, 2, 1);
INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (507, 'h2', 43, 169, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '1+2+…+4 =', '["12.5","16","10","20"]', '{"index":2}', '动态随机题型（每次闯关随机生成参数与选项）', 'c43_g0_2', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>{const n=R(3,9);return mkg(\'1+2+…+\'+n+\' =\',String(n*(n+1)/2),[String(n*(n+1)),String(n*n),String((n+1)*(n+1)/2)]);}","sampleStem":"1+2+…+4 ="}', 1, '["高二","第4章 数列","动态随机"]', 'PROTOTYPE', 1, 3, 1);
INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (508, 'h2', 43, 170, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '等差数列 a₁=4，d=3，则 a4 = 4+3×3 =', '["12","13","16","22"]', '{"index":1}', '动态随机题型（每次闯关随机生成参数与选项）', 'c43_g1_0', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>{const a1=R(1,5),d=R(1,4),n=R(3,6);return mkg(\'等差数列 a₁=\'+a1+\'，d=\'+d+\'，则 a\'+n+\' = \'+a1+\'+\'+(n-1)+\'×\'+d+\' =\',String(a1+(n-1)*d),[String(a1+n*d),String(a1+(n-1)*d+d*d),String(a1*d)])}","sampleStem":"等差数列 a₁=4，d=3，则 a4 = 4+3×3 ="}', 2, '["高二","第4章 数列","动态随机"]', 'PROTOTYPE', 1, 1, 1);
INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (509, 'h2', 43, 170, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '等比数列 a₁=1，q=3，则 a4 =', '["12","81","13","27"]', '{"index":3}', '动态随机题型（每次闯关随机生成参数与选项）', 'c43_g1_1', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>{const a1=R(1,3),q=R(2,3),n=R(3,4);return mkg(\'等比数列 a₁=\'+a1+\'，q=\'+q+\'，则 a\'+n+\' =\',String(a1*Math.pow(q,n-1)),[String(a1*q*n),String(a1*Math.pow(q,n)),String(a1+n*q)])}","sampleStem":"等比数列 a₁=1，q=3，则 a4 ="}', 2, '["高二","第4章 数列","动态随机"]', 'PROTOTYPE', 1, 2, 1);
INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (510, 'h2', 43, 170, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '等差数列前 n 项和 Sₙ = n(a₁+aₙ)/2，a₁=4，aₙ=10，n=7，Sₙ =', '["7","105","49","77"]', '{"index":2}', '动态随机题型（每次闯关随机生成参数与选项）', 'c43_g1_2', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>{const a=R(1,5),n=R(4,8);return mkg(\'等差数列前 n 项和 Sₙ = n(a₁+aₙ)/2，a₁=\'+a+\'，aₙ=\'+(a+n-1)+\'，n=\'+n+\'，Sₙ =\',String(n*(2*a+n-1)/2),[String(n*(2*a+n)),String(n*(a+n)),String((2*a+n-1)/2)]);}","sampleStem":"等差数列前 n 项和 Sₙ = n(a₁+aₙ)/2，a₁=4，aₙ=10，n=7，Sₙ ="}', 2, '["高二","第4章 数列","动态随机"]', 'PROTOTYPE', 1, 3, 1);
INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (511, 'h2', 43, 171, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '等差数列中 S₅ = 5a₃，这说明等差中项性质：S₅ = 5×a₃，若 a₃ = 2，则 S₅ =', '["20","7","10","4"]', '{"index":2}', '动态随机题型（每次闯关随机生成参数与选项）', 'c43_g2_0', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>{const a=R(1,3);return mkg(\'等差数列中 S₅ = 5a₃，这说明等差中项性质：S₅ = 5×a₃，若 a₃ = \'+a+\'，则 S₅ =\',String(5*a),[String(a*a),String(5+a),String(10*a)])}","sampleStem":"等差数列中 S₅ = 5a₃，这说明等差中项性质：S₅ = 5×a₃，若 a₃ = 2，则 S₅ ="}', 3, '["高二","第4章 数列","动态随机"]', 'PROTOTYPE', 1, 1, 1);
INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (512, 'h2', 43, 171, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '等比数列 aₙ>0，a₁a₅ = a₃²，这体现', '["等差中项性质","求和公式","递推公式","等比中项性质"]', '{"index":3}', '动态随机题型（每次闯关随机生成参数与选项）', 'c43_g2_1', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>mkg(\'等比数列 aₙ>0，a₁a₅ = a₃²，这体现\',\'等比中项性质\',[\'等差中项性质\',\'求和公式\',\'递推公式\'])","sampleStem":"等比数列 aₙ>0，a₁a₅ = a₃²，这体现"}', 3, '["高二","第4章 数列","动态随机"]', 'PROTOTYPE', 1, 2, 1);
INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (513, 'h2', 43, 171, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '无穷等比数列 |q|<1 求和：1+1/3+1/9+… = 3/2，q=3 时为', '["1/3","1","3/2","2/3"]', '{"index":2}', '动态随机题型（每次闯关随机生成参数与选项）', 'c43_g2_2', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>{const q=R(2,3);return mkg(\'无穷等比数列 |q|<1 求和：1+1/\'+q+\'+1/\'+(q*q)+\'+… = \'+q+\'/\'+(q-1)+\'，q=\'+q+\' 时为\',frac(q,q-1),[frac(q-1,q),\'1\',frac(1,q)]);}","sampleStem":"无穷等比数列 |q|<1 求和：1+1/3+1/9+… = 3/2，q=3 时为"}', 3, '["高二","第4章 数列","动态随机"]', 'PROTOTYPE', 1, 3, 1);
INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (514, 'h2', 43, 172, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '等差数列 a₁=4，d=3，前 10 项和 S₁₀ = 10a₁+45d =', '["155","205","70","175"]', '{"index":3}', '动态随机题型（每次闯关随机生成参数与选项）', 'c43_g3_0', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>{const a=R(1,4),d=R(1,3);return mkg(\'等差数列 a₁=\'+a+\'，d=\'+d+\'，前 10 项和 S₁₀ = 10a₁+45d =\',String(10*a+45*d),[String(10*a+10*d),String(10*a+55*d),String(5*a+45*d)])}","sampleStem":"等差数列 a₁=4，d=3，前 10 项和 S₁₀ = 10a₁+45d ="}', 4, '["高二","第4章 数列","动态随机"]', 'PROTOTYPE', 1, 1, 1);
INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (515, 'h2', 43, 172, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '等比数列 1,3,9,27 的前 4 项和是', '["81","80","40","12"]', '{"index":2}', '动态随机题型（每次闯关随机生成参数与选项）', 'c43_g3_1', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>{const q=R(2,3);return mkg(\'等比数列 1,\'+q+\',\'+(q*q)+\',\'+(q*q*q)+\' 的前 4 项和是\',String(1+q+q*q+q*q*q),[String(q*q*q*q),String(q*q*q*q-1),String(4*q)])}","sampleStem":"等比数列 1,3,9,27 的前 4 项和是"}', 4, '["高二","第4章 数列","动态随机"]', 'PROTOTYPE', 1, 2, 1);
INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (516, 'h2', 43, 172, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '数列 1×2+2×3+…+n(n+1) 的求和技巧是', '["等差求和","裂项相消","数学归纳","错位相减"]', '{"index":1}', '动态随机题型（每次闯关随机生成参数与选项）', 'c43_g3_2', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>{return mkg(\'数列 1×2+2×3+…+n(n+1) 的求和技巧是\',\'裂项相消\',[\'等差求和\',\'数学归纳\',\'错位相减\']);}","sampleStem":"数列 1×2+2×3+…+n(n+1) 的求和技巧是"}', 4, '["高二","第4章 数列","动态随机"]', 'PROTOTYPE', 1, 3, 1);
INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (517, 'h2', 44, 173, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '(x^2)\' =', '["x^1","2x","2x^2","2x^1"]', '{"index":3}', '动态随机题型（每次闯关随机生成参数与选项）', 'c44_g0_0', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>{const k=R(2,6);return mkg(\\"(x^\\"+k+\\")\' =\\",k+\'x^\'+(k-1),[k+\'x^\'+k,\'x^\'+(k-1),k+\'x\'])}","sampleStem":"(x^2)\' ="}', 1, '["高二","第5章 一元函数的导数及其应用","动态随机"]', 'PROTOTYPE', 1, 1, 1);
