INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (526, 'h2', 44, 176, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', 'y=x² 在 x=3 处的切线方程是 y−9 = 3(x−3)·2 中斜率为', '["2","6","9","3"]', '{"index":1}', '动态随机题型（每次闯关随机生成参数与选项）', 'c44_g3_0', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>{const k=R(2,4);return mkg(\'y=x² 在 x=\'+k+\' 处的切线方程是 y−\'+(k*k)+\' = \'+k+\'(x−\'+k+\')·2 中斜率为\',String(2*k),[String(k),String(k*k),\'2\'])}","sampleStem":"y=x² 在 x=3 处的切线方程是 y−9 = 3(x−3)·2 中斜率为"}', 4, '["高二","第5章 一元函数的导数及其应用","动态随机"]', 'PROTOTYPE', 1, 1, 1);
INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (527, 'h2', 44, 176, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', 'f(x)=x³−3x² 在 [0,3] 上的最小值是', '["0","−2","−3","−4"]', '{"index":3}', '动态随机题型（每次闯关随机生成参数与选项）', 'c44_g3_1', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>mkg(\'f(x)=x³−3x² 在 [0,3] 上的最小值是\',\'−4\',[\'0\',\'−2\',\'−3\'])","sampleStem":"f(x)=x³−3x² 在 [0,3] 上的最小值是"}', 4, '["高二","第5章 一元函数的导数及其应用","动态随机"]', 'PROTOTYPE', 1, 2, 1);
INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (528, 'h2', 44, 176, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '若 f(x)=x³+ax 在 R 上单调递增，则 a 的范围', '["a > 1","a ≥ 3","a ≥ 0","a ≤ 0"]', '{"index":2}', '动态随机题型（每次闯关随机生成参数与选项）', 'c44_g3_2', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>{return mkg(\'若 f(x)=x³+ax 在 R 上单调递增，则 a 的范围\',\'a ≥ 0\',[\'a ≤ 0\',\'a > 1\',\'a ≥ 3\']);}","sampleStem":"若 f(x)=x³+ax 在 R 上单调递增，则 a 的范围"}', 4, '["高二","第5章 一元函数的导数及其应用","动态随机"]', 'PROTOTYPE', 1, 3, 1);
INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (529, 'h2', 45, 177, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '完成一件事需两步，第一步 4 种方法，第二步 2 种，共有', '["9","14","6","8"]', '{"index":3}', '动态随机题型（每次闯关随机生成参数与选项）', 'c45_g0_0', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>{const m=R(2,4),n=R(2,4);return mkg(\'完成一件事需两步，第一步 \'+m+\' 种方法，第二步 \'+n+\' 种，共有\',String(m*n),[String(m+n),String(m+n*n),String(m*n+m+n)])}","sampleStem":"完成一件事需两步，第一步 4 种方法，第二步 2 种，共有"}', 1, '["高二","第6章 计数原理","动态随机"]', 'PROTOTYPE', 1, 1, 1);
