INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (550, 'h2', 46, 184, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '独立重复试验每次成功率为 0.5，连做 2 次恰成功 1 次的概率', '["-0.5","0.25","1.5","0.5"]', '{"index":3}', '动态随机题型（每次闯关随机生成参数与选项）', 'c46_g3_0', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>{const p=R(1,2)/4;return mkg(\'独立重复试验每次成功率为 \'+p+\'，连做 2 次恰成功 1 次的概率\',String(2*p*(1-p)),[String(p*p),String(p),\'0.5\'])}","sampleStem":"独立重复试验每次成功率为 0.5，连做 2 次恰成功 1 次的概率"}', 4, '["高二","第7章 随机变量及其分布","动态随机"]', 'PROTOTYPE', 1, 1, 1);
