INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (572, 'h3', 48, 191, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', 'f(x)=x²+1 在 R 上无零点的条件是 1 > 0，取 1=1，零点个数', '["2","3","1","0"]', '{"index":3}', '动态随机题型（每次闯关随机生成参数与选项）', 'c48_g2_1', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>{const a=R(1,2);return mkg(\'f(x)=x²+\'+a+\' 在 R 上无零点的条件是 \'+a+\' > 0，取 \'+a+\'=\'+a+\'，零点个数\',\'0\',[\'1\',\'2\',\'3\'])}","sampleStem":"f(x)=x²+1 在 R 上无零点的条件是 1 > 0，取 1=1，零点个数"}', 3, '["高三","专题1 函数与导数综合","动态随机"]', 'PROTOTYPE', 1, 2, 1);
INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (573, 'h3', 48, 191, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '若 f′(x) > 0 在 (a,b) 恒成立，则 f 在 (a,b) 上', '["先增后减","单调递增","单调递减","无法确定"]', '{"index":1}', '动态随机题型（每次闯关随机生成参数与选项）', 'c48_g2_2', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>{return mkg(\'若 f′(x) > 0 在 (a,b) 恒成立，则 f 在 (a,b) 上\',\'单调递增\',[\'单调递减\',\'先增后减\',\'无法确定\']);}","sampleStem":"若 f′(x) > 0 在 (a,b) 恒成立，则 f 在 (a,b) 上"}', 3, '["高三","专题1 函数与导数综合","动态随机"]', 'PROTOTYPE', 1, 3, 1);
INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (574, 'h3', 48, 192, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', 'f(x)=x³−3x 在 [−2,2] 上的最大值是', '["−2","2","√3","4"]', '{"index":1}', '动态随机题型（每次闯关随机生成参数与选项）', 'c48_g3_0', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>mkg(\'f(x)=x³−3x 在 [−2,2] 上的最大值是\',\'2\',[\'−2\',\'√3\',\'4\'])","sampleStem":"f(x)=x³−3x 在 [−2,2] 上的最大值是"}', 4, '["高三","专题1 函数与导数综合","动态随机"]', 'PROTOTYPE', 1, 1, 1);
INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (575, 'h3', 48, 192, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', 'f(x)=eˣ−ax 在 x=0 处切线斜率是 1−a，a=4 时斜率为', '["3","4","0","-3"]', '{"index":3}', '动态随机题型（每次闯关随机生成参数与选项）', 'c48_g3_1', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>{const a=R(2,4);return mkg(\'f(x)=eˣ−ax 在 x=0 处切线斜率是 1−a，a=\'+a+\' 时斜率为\',String(1-a),[String(a),\'0\',String(a-1)])}","sampleStem":"f(x)=eˣ−ax 在 x=0 处切线斜率是 1−a，a=4 时斜率为"}', 4, '["高三","专题1 函数与导数综合","动态随机"]', 'PROTOTYPE', 1, 2, 1);
INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (576, 'h3', 48, 192, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', 'f(x)=ln x 与 g(x)=1/x 交点个数', '["无数","0","2","1"]', '{"index":3}', '动态随机题型（每次闯关随机生成参数与选项）', 'c48_g3_2', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>{return mkg(\'f(x)=ln x 与 g(x)=1/x 交点个数\',\'1\',[\'0\',\'2\',\'无数\']);}","sampleStem":"f(x)=ln x 与 g(x)=1/x 交点个数"}', 4, '["高三","专题1 函数与导数综合","动态随机"]', 'PROTOTYPE', 1, 3, 1);
INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (577, 'h3', 49, 193, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '斜率存在的两直线平行，斜率', '["之积为 1","之积为 −1","互为相反数","相等"]', '{"index":3}', '动态随机题型（每次闯关随机生成参数与选项）', 'c49_g0_0', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>{const k=R(1,4);return mkg(\'斜率存在的两直线平行，斜率\',\'相等\',[\'互为相反数\',\'之积为 −1\',\'之积为 1\'])}","sampleStem":"斜率存在的两直线平行，斜率"}', 1, '["高三","专题2 解析几何综合","动态随机"]', 'PROTOTYPE', 1, 1, 1);
