INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (579, 'h3', 49, 193, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '抛物线的焦点与准线的距离等于 p（y²=2px），p=4 时距离是', '["2","1","8","4"]', '{"index":3}', '动态随机题型（每次闯关随机生成参数与选项）', 'c49_g0_2', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>{return mkg(\'抛物线的焦点与准线的距离等于 p（y²=2px），p=4 时距离是\',\'4\',[\'2\',\'8\',\'1\']);}","sampleStem":"抛物线的焦点与准线的距离等于 p（y²=2px），p=4 时距离是"}', 1, '["高三","专题2 解析几何综合","动态随机"]', 'PROTOTYPE', 1, 3, 1);
INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (580, 'h3', 49, 194, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '椭圆 x²/16+y²=1 的顶点（长轴端点）是', '["(±16,0)","(±1,0)","(0,±4)","(±4,0)"]', '{"index":3}', '动态随机题型（每次闯关随机生成参数与选项）', 'c49_g1_0', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>{const a=R(2,4);return mkg(\'椭圆 x²/\'+(a*a)+\'+y²=1 的顶点（长轴端点）是\',\'(±\'+a+\',0)\',[\'(0,±\'+a+\')\',\'(±1,0)\',\'(±\'+(a*a)+\',0)\'])}","sampleStem":"椭圆 x²/16+y²=1 的顶点（长轴端点）是"}', 2, '["高三","专题2 解析几何综合","动态随机"]', 'PROTOTYPE', 1, 1, 1);
