INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (582, 'h3', 49, 194, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '圆 x²+y²−2x=0 的圆心是', '["(−1,0)","(0,0)","(0,1)","(1,0)"]', '{"index":3}', '动态随机题型（每次闯关随机生成参数与选项）', 'c49_g1_2', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>{const r=R(1,3);return mkg(\'圆 x²+y²−\'+(2*r)+\'x=0 的圆心是\',\'(\'+r+\',0)\',[\'(0,\'+r+\')\',\'(−\'+r+\',0)\',\'(0,0)\']);}","sampleStem":"圆 x²+y²−2x=0 的圆心是"}', 2, '["高三","专题2 解析几何综合","动态随机"]', 'PROTOTYPE', 1, 3, 1);
INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (583, 'h3', 49, 195, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '椭圆焦点三角形面积常用结论中，b、c 关系是', '["a²+c² = b²","b = c","b²+c² = a²","a²+b² = c²"]', '{"index":2}', '动态随机题型（每次闯关随机生成参数与选项）', 'c49_g2_0', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>mkg(\'椭圆焦点三角形面积常用结论中，b、c 关系是\',\'b²+c² = a²\',[\'a²+b² = c²\',\'a²+c² = b²\',\'b = c\'])","sampleStem":"椭圆焦点三角形面积常用结论中，b、c 关系是"}', 3, '["高三","专题2 解析几何综合","动态随机"]', 'PROTOTYPE', 1, 1, 1);
INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (584, 'h3', 49, 195, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '双曲线 x²−y²/2²=1 的渐近线是', '["y=±x","y=±4x","y=±2x","y=±x/2"]', '{"index":2}', '动态随机题型（每次闯关随机生成参数与选项）', 'c49_g2_1', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>{const a=R(2,3);return mkg(\'双曲线 x²−y²/\'+a+\'²=1 的渐近线是\',\'y=±\'+a+\'x\',[\'y=±x/\'+a,\'y=±\'+(a*a)+\'x\',\'y=±x\'])}","sampleStem":"双曲线 x²−y²/2²=1 的渐近线是"}', 3, '["高三","专题2 解析几何综合","动态随机"]', 'PROTOTYPE', 1, 2, 1);
INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (585, 'h3', 49, 195, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '直线 3x+y−1=0 与圆 x²+y²=1 相交于两点（圆心距 < 1），3=0 时圆心距为', '["1","0","√2","1/2"]', '{"index":0}', '动态随机题型（每次闯关随机生成参数与选项）', 'c49_g2_2', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>{const k=R(1,3);return mkg(\'直线 \'+k+\'x+y−1=0 与圆 x²+y²=1 相交于两点（圆心距 < 1），\'+k+\'=0 时圆心距为\',\'1\',[\'0\',\'√2\',\'1/2\']);}","sampleStem":"直线 3x+y−1=0 与圆 x²+y²=1 相交于两点（圆心距 < 1），3=0 时圆心距为"}', 3, '["高三","专题2 解析几何综合","动态随机"]', 'PROTOTYPE', 1, 3, 1);
