INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (588, 'h3', 49, 196, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '点差法处理中点弦问题利用了', '["参数方程","两端点坐标差与椭圆方程作差","求导","韦达定理之外不行"]', '{"index":1}', '动态随机题型（每次闯关随机生成参数与选项）', 'c49_g3_2', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>{return mkg(\'点差法处理中点弦问题利用了\',\'两端点坐标差与椭圆方程作差\',[\'求导\',\'韦达定理之外不行\',\'参数方程\']);}","sampleStem":"点差法处理中点弦问题利用了"}', 4, '["高三","专题2 解析几何综合","动态随机"]', 'PROTOTYPE', 1, 3, 1);
INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (589, 'h3', 50, 197, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '二项分布 B(n,p) 的期望公式', '["E = p","E = n(1−p)","E = np","E = n"]', '{"index":2}', '动态随机题型（每次闯关随机生成参数与选项）', 'c50_g0_0', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>mkg(\'二项分布 B(n,p) 的期望公式\',\'E = np\',[\'E = p\',\'E = n\',\'E = n(1−p)\'])","sampleStem":"二项分布 B(n,p) 的期望公式"}', 1, '["高三","专题3 概率统计综合","动态随机"]', 'PROTOTYPE', 1, 1, 1);
INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (590, 'h3', 50, 197, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '超几何分布适用于', '["连续试验","不放回抽样","有放回抽样","正态数据"]', '{"index":1}', '动态随机题型（每次闯关随机生成参数与选项）', 'c50_g0_1', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>mkg(\'超几何分布适用于\',\'不放回抽样\',[\'有放回抽样\',\'连续试验\',\'正态数据\'])","sampleStem":"超几何分布适用于"}', 1, '["高三","专题3 概率统计综合","动态随机"]', 'PROTOTYPE', 1, 2, 1);
INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (591, 'h3', 50, 197, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', 'X~B(2,0.8)，P(X=0) = (1−0.8)² =', '["1","0.03999999999999998","0.6400000000000001","0.8"]', '{"index":1}', '动态随机题型（每次闯关随机生成参数与选项）', 'c50_g0_2', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>{const p=R(1,4)/5;return mkg(\'X~B(2,\'+p+\')，P(X=0) = (1−\'+p+\')² =\',String((1-p)*(1-p)),[String(p*p),String(p),\'1\']);}","sampleStem":"X~B(2,0.8)，P(X=0) = (1−0.8)² ="}', 1, '["高三","专题3 概率统计综合","动态随机"]', 'PROTOTYPE', 1, 3, 1);
INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (592, 'h3', 50, 198, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', 'X~B(6,0.25) 的方差 D = np(1−p) =', '["0.1875","1.125","6","1.5"]', '{"index":1}', '动态随机题型（每次闯关随机生成参数与选项）', 'c50_g1_0', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>{const n=R(4,6),p=R(1,2)/4;return mkg(\'X~B(\'+n+\',\'+p+\') 的方差 D = np(1−p) =\',String(n*p*(1-p)),[String(n*p),String((1-p)*p),String(n)])}","sampleStem":"X~B(6,0.25) 的方差 D = np(1−p) ="}', 2, '["高三","专题3 概率统计综合","动态随机"]', 'PROTOTYPE', 1, 1, 1);
INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (593, 'h3', 50, 198, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '正态分布 N(1,4) 中 σ =', '["2","4","√2","1"]', '{"index":0}', '动态随机题型（每次闯关随机生成参数与选项）', 'c50_g1_1', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>mkg(\'正态分布 N(1,4) 中 σ =\',\'2\',[\'1\',\'4\',\'√2\'])","sampleStem":"正态分布 N(1,4) 中 σ ="}', 2, '["高三","专题3 概率统计综合","动态随机"]', 'PROTOTYPE', 1, 2, 1);
INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (594, 'h3', 50, 198, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '样本均值 x̄ 的性质：Σ(xᵢ−x̄) =', '["n","0","1","x̄"]', '{"index":1}', '动态随机题型（每次闯关随机生成参数与选项）', 'c50_g1_2', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>{return mkg(\'样本均值 x̄ 的性质：Σ(xᵢ−x̄) =\',\'0\',[\'1\',\'n\',\'x̄\']);}","sampleStem":"样本均值 x̄ 的性质：Σ(xᵢ−x̄) ="}', 2, '["高三","专题3 概率统计综合","动态随机"]', 'PROTOTYPE', 1, 3, 1);
INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (595, 'h3', 50, 199, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '两个独立随机变量 X、Y，则 E(X+Y) =', '["E(X)·E(Y)","E(X)−E(Y)","E(XY)","E(X)+E(Y)"]', '{"index":3}', '动态随机题型（每次闯关随机生成参数与选项）', 'c50_g2_0', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>mkg(\'两个独立随机变量 X、Y，则 E(X+Y) =\',\'E(X)+E(Y)\',[\'E(X)·E(Y)\',\'E(X)−E(Y)\',\'E(XY)\'])","sampleStem":"两个独立随机变量 X、Y，则 E(X+Y) ="}', 3, '["高三","专题3 概率统计综合","动态随机"]', 'PROTOTYPE', 1, 1, 1);
INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (596, 'h3', 50, 199, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '掷 6 次骰子出现 6 点次数 X 服从', '["超几何分布","N(0,1)","B(6,1/6)","B(6,1/2)"]', '{"index":2}', '动态随机题型（每次闯关随机生成参数与选项）', 'c50_g2_1', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>{const n=R(4,6);return mkg(\'掷 \'+n+\' 次骰子出现 6 点次数 X 服从\',\'B(\'+n+\',1/6)\',[\'B(\'+n+\',1/2)\',\'N(0,1)\',\'超几何分布\'])}","sampleStem":"掷 6 次骰子出现 6 点次数 X 服从"}', 3, '["高三","专题3 概率统计综合","动态随机"]', 'PROTOTYPE', 1, 2, 1);
INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (597, 'h3', 50, 199, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '回归分析中用 χ²（卡方）检验的是', '["数值相关性","均值差异","方差齐性","分类变量的关联"]', '{"index":3}', '动态随机题型（每次闯关随机生成参数与选项）', 'c50_g2_2', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>{return mkg(\'回归分析中用 χ²（卡方）检验的是\',\'分类变量的关联\',[\'数值相关性\',\'方差齐性\',\'均值差异\']);}","sampleStem":"回归分析中用 χ²（卡方）检验的是"}', 3, '["高三","专题3 概率统计综合","动态随机"]', 'PROTOTYPE', 1, 3, 1);
INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (598, 'h3', 50, 200, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', 'X~B(3,0.25)，P(X≥1) = 1−(1−0.25)³，p=0.25 时为', '["0.578125","0.015625","0.25","0.5"]', '{"index":0}', '动态随机题型（每次闯关随机生成参数与选项）', 'c50_g3_0', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>{const p=R(1,2)/4;return mkg(\'X~B(3,\'+p+\')，P(X≥1) = 1−(1−\'+p+\')³，p=\'+p+\' 时为\',String(1-(1-p)*(1-p)*(1-p)),[String(p*p*p),String(p),\'0.5\'])}","sampleStem":"X~B(3,0.25)，P(X≥1) = 1−(1−0.25)³，p=0.25 时为"}', 4, '["高三","专题3 概率统计综合","动态随机"]', 'PROTOTYPE', 1, 1, 1);
INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (599, 'h3', 50, 200, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '决策时若 χ² > 6.635，则认为两变量有关（α=0.01）的理由是', '["χ² 一定正确","P(χ²>6.635)≈0.01","无法解释","样本量大"]', '{"index":1}', '动态随机题型（每次闯关随机生成参数与选项）', 'c50_g3_1', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>mkg(\'决策时若 χ² > 6.635，则认为两变量有关（α=0.01）的理由是\',\'P(χ²>6.635)≈0.01\',[\'χ² 一定正确\',\'样本量大\',\'无法解释\'])","sampleStem":"决策时若 χ² > 6.635，则认为两变量有关（α=0.01）的理由是"}', 4, '["高三","专题3 概率统计综合","动态随机"]', 'PROTOTYPE', 1, 2, 1);
INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (600, 'h3', 50, 200, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '正态总体 N(μ,σ²) 中 P(|X−μ|<σ) ≈', '["0.6827","0.9545","0.9973","0.5"]', '{"index":0}', '动态随机题型（每次闯关随机生成参数与选项）', 'c50_g3_2', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>{return mkg(\'正态总体 N(μ,σ²) 中 P(|X−μ|<σ) ≈\',\'0.6827\',[\'0.9545\',\'0.9973\',\'0.5\']);}","sampleStem":"正态总体 N(μ,σ²) 中 P(|X−μ|<σ) ≈"}', 4, '["高三","专题3 概率统计综合","动态随机"]', 'PROTOTYPE', 1, 3, 1);
INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (601, 'h3', 51, 201, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '正弦定理：a/sin A =', '["c/sin C 的倒数","2R（外接圆直径）","R","sin A"]', '{"index":1}', '动态随机题型（每次闯关随机生成参数与选项）', 'c51_g0_0', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>mkg(\'正弦定理：a/sin A =\',\'2R（外接圆直径）\',[\'R\',\'sin A\',\'c/sin C 的倒数\'])","sampleStem":"正弦定理：a/sin A ="}', 1, '["高三","专题4 解三角形与数列综合","动态随机"]', 'PROTOTYPE', 1, 1, 1);
INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (602, 'h3', 51, 201, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '△ABC 中 a=3、b=4、C=60°，用余弦定理 c² = a²+b²−2ab·cos C，a=3 时 c² =', '["-7","37","13","25"]', '{"index":2}', '动态随机题型（每次闯关随机生成参数与选项）', 'c51_g0_1', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>{const a=R(3,5);return mkg(\'△ABC 中 a=\'+a+\'、b=4、C=60°，用余弦定理 c² = a²+b²−2ab·cos C，a=\'+a+\' 时 c² =\',String(a*a+16-4*a),[String(a*a+16),String(a*a+16+4*a),String(a*a-16)])}","sampleStem":"△ABC 中 a=3、b=4、C=60°，用余弦定理 c² = a²+b²−2ab·cos C，a=3 时 c² ="}', 1, '["高三","专题4 解三角形与数列综合","动态随机"]', 'PROTOTYPE', 1, 2, 1);
INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (603, 'h3', 51, 201, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '等差数列 1,4,7 的公差是', '["3","6","4","1"]', '{"index":0}', '动态随机题型（每次闯关随机生成参数与选项）', 'c51_g0_2', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>{const d=R(1,4);return mkg(\'等差数列 1,\'+(1+d)+\',\'+(1+2*d)+\' 的公差是\',String(d),[String(d+1),\'1\',String(2*d)]);}","sampleStem":"等差数列 1,4,7 的公差是"}', 1, '["高三","专题4 解三角形与数列综合","动态随机"]', 'PROTOTYPE', 1, 3, 1);
INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (604, 'h3', 51, 202, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '△ABC 中 A=50°，则 B、C 的关系不可能是 B=C=65° 时 A 为锐角，A=60° 时 B+C =', '["120°","90°","180°","60°"]', '{"index":0}', '动态随机题型（每次闯关随机生成参数与选项）', 'c51_g1_0', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>{const n=R(3,6);return mkg(\'△ABC 中 A=\'+(90-n*10)+\'°，则 B、C 的关系不可能是 B=C=\'+(45+n*5)+\'° 时 A 为锐角，A=60° 时 B+C =\',\'120°\',[\'60°\',\'90°\',\'180°\'])}","sampleStem":"△ABC 中 A=50°，则 B、C 的关系不可能是 B=C=65° 时 A 为锐角，A=60° 时 B+C ="}', 2, '["高三","专题4 解三角形与数列综合","动态随机"]', 'PROTOTYPE', 1, 1, 1);
INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (605, 'h3', 51, 202, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', 'a=2、b=2、A=30°，则 B =', '["60°","30° 或 150°","只能 30°","只能 150°"]', '{"index":1}', '动态随机题型（每次闯关随机生成参数与选项）', 'c51_g1_1', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>{const a=R(2,4);return mkg(\'a=2、b=2、A=30°，则 B =\',\'30° 或 150°\',[\'只能 30°\',\'只能 150°\',\'60°\'])}","sampleStem":"a=2、b=2、A=30°，则 B ="}', 2, '["高三","专题4 解三角形与数列综合","动态随机"]', 'PROTOTYPE', 1, 2, 1);
INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (606, 'h3', 51, 202, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '已知 1/[n(n+1)] = 1/n − 1/(n+1)，则 1/[4×5] =', '["1/9","1/4 + 1/5","1/4 − 1/5","1/5 − 1/4"]', '{"index":2}', '动态随机题型（每次闯关随机生成参数与选项）', 'c51_g1_2', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>{const n=R(3,8);return mkg(\'已知 1/[n(n+1)] = 1/n − 1/(n+1)，则 1/[4×5] =\',\'1/4 − 1/5\',[\'1/4 + 1/5\',\'1/5 − 1/4\',\'1/9\']);}","sampleStem":"已知 1/[n(n+1)] = 1/n − 1/(n+1)，则 1/[4×5] ="}', 2, '["高三","专题4 解三角形与数列综合","动态随机"]', 'PROTOTYPE', 1, 3, 1);
INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (607, 'h3', 51, 203, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '△ABC 中 a=4，A=60°，b=c，则 b =', '["8","4","16","2"]', '{"index":1}', '动态随机题型（每次闯关随机生成参数与选项）', 'c51_g2_0', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>{const a=R(3,6);return mkg(\'△ABC 中 a=\'+a+\'，A=60°，b=c，则 b =\',String(a),[String(a/2),String(2*a),String(a*a)])}","sampleStem":"△ABC 中 a=4，A=60°，b=c，则 b ="}', 3, '["高三","专题4 解三角形与数列综合","动态随机"]', 'PROTOTYPE', 1, 1, 1);
INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (608, 'h3', 51, 203, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '等比数列 1,2,4… 的前 n 项和 Sₙ = (2ⁿ−1)/1，q=2，S₃ = 2²+2+1 =', '["2","6","7","8"]', '{"index":2}', '动态随机题型（每次闯关随机生成参数与选项）', 'c51_g2_1', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>{const q=R(2,3);return mkg(\'等比数列 1,\'+q+\',\'+(q*q)+\'… 的前 n 项和 Sₙ = (\'+q+\'ⁿ−1)/\'+(q-1)+\'，q=\'+q+\'，S₃ = \'+q+\'²+\'+q+\'+1 =\',String(q*q+q+1),[String(q*q*q),String(q*q-q),String(3*q)])}","sampleStem":"等比数列 1,2,4… 的前 n 项和 Sₙ = (2ⁿ−1)/1，q=2，S₃ = 2²+2+1 ="}', 3, '["高三","专题4 解三角形与数列综合","动态随机"]', 'PROTOTYPE', 1, 2, 1);
INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (609, 'h3', 51, 203, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '余弦定理中 cos B = 0 等价于', '["c² = a²+b² 之外不可能","B = 60°","a = b","B = 90°"]', '{"index":3}', '动态随机题型（每次闯关随机生成参数与选项）', 'c51_g2_2', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>{return mkg(\'余弦定理中 cos B = 0 等价于\',\'B = 90°\',[\'B = 60°\',\'a = b\',\'c² = a²+b² 之外不可能\']);}","sampleStem":"余弦定理中 cos B = 0 等价于"}', 3, '["高三","专题4 解三角形与数列综合","动态随机"]', 'PROTOTYPE', 1, 3, 1);
INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (610, 'h3', 51, 204, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '△ABC 中 sin A:sin B:sin C = 2:2:2，则最大角 B 满足 cos B = (2a²−4)/(2a²) ，a=2 时 cos B =', '["1/2−1","1/2","1/2+1","1"]', '{"index":1}', '动态随机题型（每次闯关随机生成参数与选项）', 'c51_g3_0', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>{const a=R(2,4);return mkg(\'△ABC 中 sin A:sin B:sin C = \'+a+\':2:\'+a+\'，则最大角 B 满足 cos B = (2a²−4)/(2a²) ，a=\'+a+\' 时 cos B =\',frac(a*a-2,a*a),[frac(a*a,a*a-2),frac(2,a*a),frac(a*a-4,a*a)])}","sampleStem":"△ABC 中 sin A:sin B:sin C = 2:2:2，则最大角 B 满足 cos B = (2a²−4)/(2a²) ，a=2 时 cos B ="}', 4, '["高三","专题4 解三角形与数列综合","动态随机"]', 'PROTOTYPE', 1, 1, 1);
INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (611, 'h3', 51, 204, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', 'Sₙ = n² 的数列 aₙ = Sₙ−Sₙ₋₁ = 2n−1，n=3 时 aₙ =', '["5","4","6","9"]', '{"index":0}', '动态随机题型（每次闯关随机生成参数与选项）', 'c51_g3_1', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>{const n=R(3,5);return mkg(\'Sₙ = n² 的数列 aₙ = Sₙ−Sₙ₋₁ = 2n−1，n=\'+n+\' 时 aₙ =\',String(2*n-1),[String(2*n),String(n*n),String(n+1)])}","sampleStem":"Sₙ = n² 的数列 aₙ = Sₙ−Sₙ₋₁ = 2n−1，n=3 时 aₙ ="}', 4, '["高三","专题4 解三角形与数列综合","动态随机"]', 'PROTOTYPE', 1, 2, 1);
INSERT IGNORE INTO edu_question (id, grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, source, version, sort_order, enabled) VALUES (612, 'h3', 51, 204, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '等差{aₙ}与等比{bₙ}，a₁=b₁=1，公差=公比=2，则 a₄ 与 b₄ 的大小', '["a₄ < b₄","无法确定","a₄ = b₄","a₄ > b₄"]', '{"index":0}', '动态随机题型（每次闯关随机生成参数与选项）', 'c51_g3_2', '{"type":"PROTOTYPE_JS_EXPR","source":"()=>mkg(\'等差{aₙ}与等比{bₙ}，a₁=b₁=1，公差=公比=2，则 a₄ 与 b₄ 的大小\',\'a₄ < b₄\',[\'a₄ > b₄\',\'a₄ = b₄\',\'无法确定\'])","sampleStem":"等差{aₙ}与等比{bₙ}，a₁=b₁=1，公差=公比=2，则 a₄ 与 b₄ 的大小"}', 4, '["高三","专题4 解三角形与数列综合","动态随机"]', 'PROTOTYPE', 1, 3, 1);